  3→using System.Reactive;
  4→using DemoApp.CollaborativeEditor.Models;
  5→using DemoApp.Shared;
  6→using Microsoft.Extensions.Logging;
  7→using Microsoft.Extensions.Logging.Abstractions;
  8→using Six.Automerge;
  9→using Six.Automerge.TextEdit;
 10→using ReactiveUI;
 11→
 12→namespace DemoApp.CollaborativeEditor.ViewModels;
 13→
 14→public class EditorViewModel : ViewModelBase, IDisposable
 15→{
 16→  readonly RepoService? _repoService;
 17→  readonly ILogger<EditorViewModel> _logger;
 18→  readonly Action<Action> _dispatcher;
 19→  TextDocument? _textDocument;
 20→  string _documentText = string.Empty;
 21→  string _syncStatus = "Disconnected";
 22→  int _cursorPosition;
 23→  int _selectionLength;
 24→  FormattedText? _formattedText;
 25→  bool _isBold;
 26→  bool _isItalic;
 27→  bool _isUnderline;
 28→  int _isRemoteUpdate;
 29→  bool _disposed;
 30→
 31→  public EditorViewModel(
 32→    RepoService? repoService = null,
 33→    ILoggerFactory? loggerFactory = null,
 34→    Action<Action>? dispatcher = null)
 35→  {
 36→    _repoService = repoService;
 37→    _logger = (loggerFactory ?? NullLoggerFactory.Instance).CreateLogger<EditorViewModel>();
 38→    _dispatcher = dispatcher ?? (action => action());
 39→
 40→    SaveCommand = ReactiveCommand.CreateFromTask(SaveDocumentAsync);
 41→    ExportJsonCommand = ReactiveCommand.CreateFromTask(ExportJsonAsync);
 42→    ToggleBoldCommand = ReactiveCommand.CreateFromTask(ToggleBoldAsync);
 43→    ToggleItalicCommand = ReactiveCommand.CreateFromTask(ToggleItalicAsync);
 44→    ToggleUnderlineCommand = ReactiveCommand.CreateFromTask(ToggleUnderlineAsync);
 45→  }
 46→
 47→  /// <summary>
 48→  /// The current text content of the local Automerge document.
 49→  /// Two-way bound to the TextBox in the view.
 50→  /// </summary>
 51→  public string DocumentText
 52→  {
 53→    get => _documentText;
 54→    set
 55→    {
 56→      if(_documentText == value)
 57→      {
 58→        return;
 59→      }
 60→
 61→      if(_textDocument is not null && Volatile.Read(ref _isRemoteUpdate) == 0)
 62→      {
 63→        _ = _textDocument.ApplyTextChangeAsync(value);
 64→      }
 65→
 66→      this.RaiseAndSetIfChanged(ref _documentText, value);
 67→    }
 68→  }
 69→
 70→  /// <summary>
 71→  /// Current sync status description.
 72→  /// </summary>
 73→  public string SyncStatus
 74→  {
 75→    get => _syncStatus;
 76→    set => this.RaiseAndSetIfChanged(ref _syncStatus, value);
 77→  }
 78→
 79→  /// <summary>
 80→  /// The current formatted text from the TextDocument, used for rich text rendering.
 81→  /// </summary>
 82→  public FormattedText? FormattedText
 83→  {
 84→    get => _formattedText;
 85→    private set
 86→    {
 87→      Console.Error.WriteLine($"[EditorViewModel] FormattedText setter: spans={value?.Spans.Count ?? 0}, text='{value?.PlainText?.Substring(0, Math.Min(30, value?.PlainText?.Length ?? 0))}'");
 88→      this.RaiseAndSetIfChanged(ref _formattedText, value);
 89→    }
 90→  }
 91→
 92→  /// <summary>
 93→  /// Current cursor position in the local document.
 94→  /// </summary>
 95→  public int CursorPosition
 96→  {
 97→    get => _cursorPosition;
 98→    set
 99→    {
100→      this.RaiseAndSetIfChanged(ref _cursorPosition, value);
101→      UpdateFormattingState();
102→    }
103→  }
104→
105→  /// <summary>
106→  /// Length of the current text selection.
107→  /// </summary>
108→  public int SelectionLength
109→  {
110→    get => _selectionLength;
111→    set => this.RaiseAndSetIfChanged(ref _selectionLength, value);
112→  }
113→
114→  /// <summary>
115→  /// Whether bold formatting is active at the cursor.
116→  /// </summary>
117→  public bool IsBold
118→  {
119→    get => _isBold;
120→    set => this.RaiseAndSetIfChanged(ref _isBold, value);
121→  }
122→
123→  /// <summary>
124→  /// Whether italic formatting is active at the cursor.
125→  /// </summary>
126→  public bool IsItalic
127→  {
128→    get => _isItalic;
129→    set => this.RaiseAndSetIfChanged(ref _isItalic, value);
130→  }
131→
132→  /// <summary>
133→  /// Whether underline formatting is active at the cursor.
134→  /// </summary>
135→  public bool IsUnderline
136→  {
137→    get => _isUnderline;
138→    set => this.RaiseAndSetIfChanged(ref _isUnderline, value);
139→  }
140→
141→  /// <summary>
142→  /// Gets the RepoService for document operations.
143→  /// </summary>
144→  internal RepoService? RepoService => _repoService;
145→
146→  /// <summary>
147→  /// Gets the TextDocument for collaborative text operations.
148→  /// </summary>
149→  internal TextDocument? TextDocument => _textDocument;
150→
151→  public ReactiveCommand<Unit, Unit> SaveCommand { get; }
152→
153→  public ReactiveCommand<Unit, Unit> ExportJsonCommand { get; }
154→
155→  public ReactiveCommand<Unit, Unit> ToggleBoldCommand { get; }
156→
157→  public ReactiveCommand<Unit, Unit> ToggleItalicCommand { get; }
158→
159→  public ReactiveCommand<Unit, Unit> ToggleUnderlineCommand { get; }
160→
161→  /// <summary>
162→  /// Sets the TextDocument and subscribes to its change events.
163→  /// Called by EditorWindow after document creation/join/resume.
164→  /// </summary>
165→  internal void SetTextDocument(TextDocument textDocument)
166→  {
167→    if(_textDocument is not null)
168→    {
169→      _textDocument.TextChanged -= OnTextChanged;
170→      _textDocument.FormattedTextChanged -= OnFormattedTextChanged;
171→    }
172→
173→    _textDocument = textDocument;
174→    _textDocument.TextChanged += OnTextChanged;
175→    _textDocument.FormattedTextChanged += OnFormattedTextChanged;
176→
177→    // Initialize UI text and formatted text from the document
178→    _documentText = _textDocument.Text;
179→    this.RaisePropertyChanged(nameof(DocumentText));
180→    FormattedText = _textDocument.FormattedText;
181→    UpdateFormattingState();
182→  }
183→
184→  void OnTextChanged(object? sender, TextChangedEventArgs e)
185→  {
186→    if(e.IsLocal)
187→    {
188→      // Local text change: the TextDocument cache is already refreshed,
189→      // so update the FormattedText binding for the display layer.
190→      _dispatcher(() => FormattedText = _textDocument?.FormattedText);
191→      return;
192→    }
193→
194→    _dispatcher(() =>
195→    {
196→      Interlocked.CompareExchange(ref _isRemoteUpdate, 1, 0);
197→      try
198→      {
199→        _logger.LogDebug("Remote update: refreshing document text ({CharCount} chars)", e.NewText.Length);
200→        _documentText = e.NewText;
201→        this.RaisePropertyChanged(nameof(DocumentText));
202→        FormattedText = _textDocument?.FormattedText;
203→      }
204→      finally
205→      {
206→        Interlocked.Exchange(ref _isRemoteUpdate, 0);
207→      }
208→    });
209→  }
210→
211→  void OnFormattedTextChanged(object? sender, FormattedTextChangedEventArgs e)
212→  {
213→    _dispatcher(UpdateFormattingState);
214→  }
215→
216→  /// <summary>
217→  /// Updates SyncStatus based on connection state and peer count.
218→  /// Called by EditorWindow when RepoService connection state or peer count changes.
219→  /// </summary>
220→  internal void UpdateConnectionStatus(ConnectionState connectionState, int peerCount)
221→  {
222→    SyncStatus = connectionState switch
223→    {
224→      ConnectionState.Connected when peerCount > 0 =>
225→        $"Syncing ({peerCount} {(peerCount == 1 ? "peer" : "peers")})",
226→      ConnectionState.Connected => "Ready",
227→      ConnectionState.Connecting => "Connecting...",
228→      ConnectionState.Reconnecting => "Reconnecting...",
229→      _ => "Disconnected"
230→    };
231→  }
232→
233→  void UpdateFormattingState()
234→  {
235→    if(_disposed || _textDocument is null)
236→    {
237→      return;
238→    }
239→
240→    FormattedText formattedText = _textDocument.FormattedText;
241→    FormattedText = formattedText;
242→    FormattingState state = FormattingState.FromFormattedText(formattedText, _cursorPosition);
243→    IsBold = state.IsBold;
244→    IsItalic = state.IsItalic;
245→    IsUnderline = state.IsUnderline;
246→  }
247→
248→  async Task ToggleBoldAsync()
249→  {
250→    Console.Error.WriteLine($"[EditorViewModel] ToggleBoldAsync: textDoc={_textDocument is not null}, sel={_selectionLength}, pos={_cursorPosition}, isBold={_isBold}");
251→    if(_textDocument is null || _selectionLength <= 0)
252→    {
253→      return;
254→    }
255→
256→    ulong start = (ulong)_cursorPosition;
257→    ulong end = (ulong)(_cursorPosition + _selectionLength);
258→    Console.Error.WriteLine($"[EditorViewModel] Applying mark: start={start}, end={end}, remove={_isBold}");
259→
260→    if(_isBold)
261→    {
262→      await _textDocument.RemoveMarkAsync("bold", start, end, ExpandMode.Both).ConfigureAwait(false);
263→    }
264→    else
265→    {
266→      await _textDocument.ApplyMarkAsync(start, end, "bold", true, ExpandMode.Both).ConfigureAwait(false);
267→    }
268→
269→    UpdateFormattingState();
270→  }
271→
272→  async Task ToggleItalicAsync()
273→  {
274→    if(_textDocument is null || _selectionLength <= 0)
275→    {
276→      return;
277→    }
278→
279→    ulong start = (ulong)_cursorPosition;
280→    ulong end = (ulong)(_cursorPosition + _selectionLength);
281→
282→    if(_isItalic)
283→    {
284→      await _textDocument.RemoveMarkAsync("italic", start, end, ExpandMode.Both).ConfigureAwait(false);
285→    }
286→    else
287→    {
288→      await _textDocument.ApplyMarkAsync(start, end, "italic", true, ExpandMode.Both).ConfigureAwait(false);
289→    }
290→
291→    UpdateFormattingState();
292→  }
293→
294→  async Task ToggleUnderlineAsync()
295→  {
296→    if(_textDocument is null || _selectionLength <= 0)
297→    {
298→      return;
299→    }
300→
301→    ulong start = (ulong)_cursorPosition;
302→    ulong end = (ulong)(_cursorPosition + _selectionLength);
303→
304→    if(_isUnderline)
305→    {
306→      await _textDocument.RemoveMarkAsync("underline", start, end, ExpandMode.Both).ConfigureAwait(false);
307→    }
308→    else
309→    {
310→      await _textDocument.ApplyMarkAsync(start, end, "underline", true, ExpandMode.Both).ConfigureAwait(false);
311→    }
312→
313→    UpdateFormattingState();
314→  }
315→
316→  async Task SaveDocumentAsync()
317→  {
318→    if(_textDocument is null)
319→    {
320→      SyncStatus = "No document loaded";
321→      return;
322→    }
323→
324→    byte[] saved = await _textDocument.Handle.ReadAsync(doc => doc.Save()).ConfigureAwait(false);
325→    SyncStatus = $"Saved ({saved.Length} bytes)";
326→  }
327→
328→  async Task ExportJsonAsync()
329→  {
330→    if(_textDocument is null)
331→    {
332→      SyncStatus = "No document loaded";
333→      return;
334→    }
335→
336→    string json = await _textDocument.Handle.ReadAsync(doc => doc.HydrateJson()).ConfigureAwait(false);
337→    _logger.LogInformation("Document JSON: {Json}", json);
338→    SyncStatus = $"Exported JSON ({json.Length} chars)";
339→  }
340→
341→  public void Dispose()
342→  {
343→    if(!_disposed)
344→    {
345→      _disposed = true;
346→
347→      if(_textDocument is not null)
348→      {
349→        _textDocument.TextChanged -= OnTextChanged;
350→        _textDocument.FormattedTextChanged -= OnFormattedTextChanged;
351→        _textDocument.Dispose();
352→      }
353→
354→      _repoService?.Dispose();
355→    }
356→  }
357→}
