  3→using Avalonia.Controls;
  4→using Avalonia.Threading;
  5→using DemoApp.CollaborativeEditor.ViewModels;
  6→using DemoApp.Shared;
  7→using DemoApp.Shared.Controls;
  8→using Microsoft.Extensions.DependencyInjection;
  9→using Microsoft.Extensions.Logging;
 10→using Microsoft.Extensions.Logging.Abstractions;
 11→using Six.Automerge.TextEdit;
 12→
 13→namespace DemoApp.CollaborativeEditor.Views;
 14→
 15→public partial class EditorWindow : Window
 16→{
 17→  readonly ILogger<EditorWindow> _logger;
 18→  DocumentSessionDialogViewModel? _sessionVm;
 19→  ConnectionStatusBarViewModel? _statusBarVm;
 20→
 21→  public EditorWindow()
 22→  {
 23→    var loggerFactory = App.Services?.GetService<ILoggerFactory>();
 24→    _logger = (loggerFactory ?? NullLoggerFactory.Instance).CreateLogger<EditorWindow>();
 25→    InitializeComponent();
 26→    Loaded += OnLoaded;
 27→  }
 28→
 29→  async void OnLoaded(object? sender, EventArgs e)
 30→  {
 31→    _sessionVm = new DocumentSessionDialogViewModel();
 32→    _sessionVm.ResultReady += OnSessionResultReady;
 33→
 34→    SessionDialog.DataContext = _sessionVm;
 35→    SessionDialog.RefreshRequested += OnRefreshRequested;
 36→
 37→    _statusBarVm = new ConnectionStatusBarViewModel();
 38→    StatusBar.DataContext = _statusBarVm;
 39→
 40→    // Track caret position and selection changes from the TextBox
 41→    LocalEditor.PropertyChanged += (_, args) =>
 42→    {
 43→      if(DataContext is not EditorViewModel vm)
 44→      {
 45→        return;
 46→      }
 47→
 48→      if(args.Property == TextBox.CaretIndexProperty)
 49→      {
 50→        vm.CursorPosition = LocalEditor.CaretIndex;
 51→      }
 52→
 53→      if(args.Property == TextBox.SelectionStartProperty || args.Property == TextBox.SelectionEndProperty)
 54→      {
 55→        int start = LocalEditor.SelectionStart;
 56→        int end = LocalEditor.SelectionEnd;
 57→        int newLength = Math.Abs(end - start);
 58→        vm.SelectionLength = newLength;
 59→      }
 60→    };
 61→
 62→    // Load stored documents, initialize connection, then fetch server documents
 63→    if(DataContext is EditorViewModel vm2 && vm2.RepoService is not null)
 64→    {
 65→      _sessionVm.LoadStoredDocuments(vm2.RepoService.StorageDirectory);
 66→      await vm2.RepoService.InitializeAsync();
 67→      WireConnectionEvents(vm2.RepoService);
 68→      await _sessionVm.LoadServerDocumentsAsync(vm2.RepoService);
 69→    }
 70→  }
 71→
 72→  async void OnRefreshRequested(object? sender, EventArgs e)
 73→  {
 74→    if(_sessionVm is null || DataContext is not EditorViewModel vm || vm.RepoService is null)
 75→    {
 76→      return;
 77→    }
 78→
 79→    await _sessionVm.LoadServerDocumentsAsync(vm.RepoService);
 80→  }
 81→
 82→  async void OnSessionResultReady(object? sender, EventArgs e)
 83→  {
 84→    if(_sessionVm?.Result is null || DataContext is not EditorViewModel vm)
 85→    {
 86→      return;
 87→    }
 88→
 89→    var result = _sessionVm.Result;
 90→    _sessionVm.IsLoading = true;
 91→    _sessionVm.ErrorMessage = null;
 92→
 93→    try
 94→    {
 95→      switch(result.Action)
 96→      {
 97→        case SessionAction.Create:
 98→          await HandleCreateAsync(vm);
 99→          break;
100→        case SessionAction.Join:
101→          await HandleJoinAsync(vm, result.DocumentId!);
102→          break;
103→        case SessionAction.Resume:
104→          await HandleResumeAsync(vm, result.DocumentId!);
105→          break;
106→      }
107→
108→      await Dispatcher.UIThread.InvokeAsync(() => _sessionVm.IsLoading = false);
109→    }
110→    catch(OperationCanceledException ex)
111→    {
112→      _logger.LogWarning(ex, "Document {Action} was cancelled", result.Action);
113→      await Dispatcher.UIThread.InvokeAsync(() =>
114→      {
115→        vm.SyncStatus = "Operation cancelled";
116→        _sessionVm.IsLoading = false;
117→      });
118→    }
119→    catch(TimeoutException ex)
120→    {
121→      _logger.LogWarning(ex, "Document {Action} timed out", result.Action);
122→      await Dispatcher.UIThread.InvokeAsync(() =>
123→      {
124→        vm.SyncStatus = "Operation timed out";
125→        _sessionVm.ErrorMessage = "The operation timed out. The document may be unavailable or the server is not responding.";
126→        _sessionVm.IsLoading = false;
127→      });
128→    }
129→    catch(Exception ex)
130→    {
131→      _logger.LogWarning(ex, "Document {Action} failed", result.Action);
132→      await Dispatcher.UIThread.InvokeAsync(() =>
133→      {
134→        vm.SyncStatus = $"Error: {ex.Message}";
135→        _sessionVm.ErrorMessage = ex.Message;
136→        _sessionVm.IsLoading = false;
137→      });
138→    }
139→  }
140→
141→  async Task HandleCreateAsync(EditorViewModel vm)
142→  {
143→    if(vm.RepoService is null)
144→    {
145→      _logger.LogInformation("Creating offline document (no RepoService)");
146→      await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Creating...");
147→
148→      // For offline mode, create a standalone repo with in-memory adapters
149→      var repo = new Six.Automerge.Repository.Repo(new Six.Automerge.Repository.RepoConfig());
150→      TextDocument textDoc = await TextDocument.CreateAsync(repo);
151→
152→      await Dispatcher.UIThread.InvokeAsync(() =>
153→      {
154→        vm.SetTextDocument(textDoc);
155→        vm.SyncStatus = "Ready (offline)";
156→      });
157→      await ShowEditorAsync(null);
158→      return;
159→    }
160→
161→    await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Creating...");
162→    await vm.RepoService.InitializeAsync();
163→    WireConnectionEvents(vm.RepoService);
164→
165→    TextDocument textDocument = await TextDocument.CreateAsync(vm.RepoService.Repo!);
166→
167→    await Dispatcher.UIThread.InvokeAsync(() =>
168→    {
169→      vm.SetTextDocument(textDocument);
170→      vm.SyncStatus = "Ready";
171→    });
172→
173→    _logger.LogInformation("Created document {DocumentId}", textDocument.DocumentId);
174→    await ShowEditorAsync(textDocument.DocumentId);
175→    await FetchInitialDocumentPeersAsync(vm.RepoService, vm, textDocument.DocumentId);
176→  }
177→
178→  async Task HandleJoinAsync(EditorViewModel vm, string documentId)
179→  {
180→    if(vm.RepoService is null)
181→    {
182→      _logger.LogWarning("Cannot join document {DocumentId}: no server connection", documentId);
183→      await Dispatcher.UIThread.InvokeAsync(() =>
184→        _sessionVm!.ErrorMessage = "Cannot join: no server connection");
185→      return;
186→    }
187→
188→    await vm.RepoService.InitializeAsync();
189→    WireConnectionEvents(vm.RepoService);
190→
191→    await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Joining...");
192→    await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Syncing...");
193→
194→    TextDocument? textDocument = await TextDocument.OpenAsync(
195→      vm.RepoService.Repo!,
196→      documentId,
197→      timeout: TimeSpan.FromSeconds(30));
198→
199→    if(textDocument is null)
200→    {
201→      _logger.LogWarning("Join failed: document {DocumentId} not found", documentId);
202→      await Dispatcher.UIThread.InvokeAsync(() =>
203→      {
204→        _sessionVm!.ErrorMessage = "Document not found";
205→        vm.SyncStatus = "Disconnected";
206→      });
207→      return;
208→    }
209→
210→    await Dispatcher.UIThread.InvokeAsync(() =>
211→    {
212→      vm.SetTextDocument(textDocument);
213→      vm.SyncStatus = "Ready";
214→    });
215→
216→    _logger.LogInformation("Joined document {DocumentId}", textDocument.DocumentId);
217→    await ShowEditorAsync(textDocument.DocumentId);
218→    await FetchInitialDocumentPeersAsync(vm.RepoService, vm, textDocument.DocumentId);
219→  }
220→
221→  async Task HandleResumeAsync(EditorViewModel vm, string documentId)
222→  {
223→    if(vm.RepoService is null)
224→    {
225→      _logger.LogWarning("Cannot resume document {DocumentId}: no server connection", documentId);
226→      await Dispatcher.UIThread.InvokeAsync(() =>
227→        _sessionVm!.ErrorMessage = "Cannot resume: no server connection");
228→      return;
229→    }
230→
231→    await vm.RepoService.InitializeAsync();
232→    WireConnectionEvents(vm.RepoService);
233→
234→    await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Resuming...");
235→
236→    TextDocument? textDocument = await TextDocument.OpenAsync(
237→      vm.RepoService.Repo!,
238→      documentId,
239→      timeout: TimeSpan.FromSeconds(10));
240→
241→    if(textDocument is null)
242→    {
243→      _logger.LogWarning("Resume failed: document {DocumentId} not found in storage", documentId);
244→      await Dispatcher.UIThread.InvokeAsync(() =>
245→      {
246→        _sessionVm!.ErrorMessage = "Document not found in storage";
247→        vm.SyncStatus = "Disconnected";
248→      });
249→      return;
250→    }
251→
252→    await Dispatcher.UIThread.InvokeAsync(() =>
253→    {
254→      vm.SetTextDocument(textDocument);
255→      vm.SyncStatus = "Ready";
256→    });
257→
258→    _logger.LogInformation("Resumed document {DocumentId}", textDocument.DocumentId);
259→    await ShowEditorAsync(textDocument.DocumentId);
260→    await FetchInitialDocumentPeersAsync(vm.RepoService, vm, textDocument.DocumentId);
261→  }
262→
263→  void WireConnectionEvents(RepoService repoService)
264→  {
265→    if(_statusBarVm is null)
266→    {
267→      return;
268→    }
269→
270→    _statusBarVm.PeerId = repoService.PeerId?.ToString();
271→    _statusBarVm.ServerUrl = repoService is { IsInitialized: true }
272→      ? "Connected"
273→      : "Offline";
274→
275→    // Set initial connection state (event handler below only fires on future changes)
276→    DemoApp.Shared.ConnectionState MapState(ConnectionState s) => s switch
277→    {
278→      ConnectionState.Connected => DemoApp.Shared.ConnectionState.Connected,
279→      ConnectionState.Connecting => DemoApp.Shared.ConnectionState.Connecting,
280→      ConnectionState.Reconnecting => DemoApp.Shared.ConnectionState.Reconnecting,
281→      _ => DemoApp.Shared.ConnectionState.Disconnected
282→    };
283→
284→    _statusBarVm.ConnectionState = MapState(repoService.ConnectionState);
285→
286→    repoService.ConnectionStateChanged += (_, state) =>
287→      Dispatcher.UIThread.Post(() =>
288→      {
289→        if(_statusBarVm is not null)
290→        {
291→          _statusBarVm.ConnectionState = MapState(state);
292→        }
293→
294→        if(DataContext is EditorViewModel vm && vm.TextDocument is not null)
295→        {
296→          vm.UpdateConnectionStatus(MapState(state), repoService.DocumentPeerCount);
297→        }
298→      });
299→
300→    repoService.DocumentPeerCountChanged += (_, count) =>
301→      Dispatcher.UIThread.Post(() =>
302→      {
303→        if(_statusBarVm is not null)
304→        {
305→          _statusBarVm.PeerCount = count;
306→        }
307→
308→        if(DataContext is EditorViewModel vm && vm.TextDocument is not null)
309→        {
310→          vm.UpdateConnectionStatus(MapState(repoService.ConnectionState), count);
311→        }
312→      });
313→  }
314→
315→  async Task FetchInitialDocumentPeersAsync(RepoService repoService, EditorViewModel vm, string documentId)
316→  {
317→    try
318→    {
319→      var peers = await repoService.GetDocumentPeersAsync(documentId);
320→      int count = peers.Count;
321→      _logger.LogInformation("Initial document peers for {DocumentId}: {PeerCount}", documentId, count);
322→
323→      await Dispatcher.UIThread.InvokeAsync(() =>
324→      {
325→        if(_statusBarVm is not null)
326→        {
327→          _statusBarVm.PeerCount = count;
328→        }
329→
330→        DemoApp.Shared.ConnectionState MapState(ConnectionState s) => s switch
331→        {
332→          ConnectionState.Connected => DemoApp.Shared.ConnectionState.Connected,
333→          ConnectionState.Connecting => DemoApp.Shared.ConnectionState.Connecting,
334→          ConnectionState.Reconnecting => DemoApp.Shared.ConnectionState.Reconnecting,
335→          _ => DemoApp.Shared.ConnectionState.Disconnected
336→        };
337→
338→        vm.UpdateConnectionStatus(MapState(repoService.ConnectionState), count);
339→      });
