135→  /// <summary>
136→  /// Initializes the repo, storage, and network adapter.
137→  /// Creates the storage directory, connects to the SignalR hub, and starts the repo.
138→  /// </summary>
139→  /// <param name="cancellationToken">Optional token to cancel the initialization.</param>
140→  public async Task InitializeAsync(CancellationToken cancellationToken = default)
141→  {
142→    ThrowIfDisposed();
143→    cancellationToken.ThrowIfCancellationRequested();
144→
145→    if(_repo is not null)
146→    {
147→      _logger.LogWarning("RepoService is already initialized");
148→      return;
149→    }
150→
151→    string resolvedUrl = ResolvedHubUrl;
152→    _logger.LogInformation("Initializing RepoService for app '{AppName}' with hub URL: {HubUrl}", _options.AppName, resolvedUrl);
153→
154→    // Create file system storage
155→    string storageDir = StorageDirectory;
156→    Directory.CreateDirectory(storageDir);
157→    _storage = new FileSystemStorageAdapter(storageDir);
158→    _logger.LogInformation("Storage initialized at: {StorageDir}", storageDir);
159→
160→    cancellationToken.ThrowIfCancellationRequested();
161→
162→    // Create SignalR connection service
163→    IOptionsMonitor<SignalRConnectionServiceOptions> optionsMonitor =
164→      new StaticOptionsMonitor(new SignalRConnectionServiceOptions
165→      {
166→        HubUrl = resolvedUrl,
167→        AutoStart = true,
168→        EnableAutomaticReconnect = true,
169→        UseMessagePackProtocol = true
170→      });
171→
172→    _connectionService = new SignalRConnectionService(_loggerFactory, optionsMonitor, string.Empty);
173→
174→    // Create network adapter
175→    _networkAdapter = new SignalRNetworkAdapter(_connectionService, _loggerFactory);
176→    _networkAdapter.DocumentPeersChanged += OnDocumentPeersChanged;
177→
178→    // Create repo
179→    _repo = new Repo(new RepoConfig
180→    {
181→      Storage = _storage,
182→      NetworkAdapters = [_networkAdapter]
183→    });
184→
185→    _logger.LogInformation("Repo created with PeerId: {PeerId}", _repo.PeerId);
186→
187→    // Wire up peer events
188→    _repo.PeerConnected += OnPeerConnected;
189→    _repo.PeerDisconnected += OnPeerDisconnected;
190→
191→    // Connect the network adapter
192→    SetConnectionState(ConnectionState.Connecting);
193→
194→    try
195→    {
196→      _networkAdapter.Connect(_repo.PeerId);
197→      await _networkAdapter.WhenReady().WaitAsync(_options.ConnectionTimeout, cancellationToken);
198→
199→      // Capture the hub connection for RPC calls (e.g., ListServerDocumentsAsync)
200→      _hubConnection = await _connectionService.GetConnection();
201→
202→      SetConnectionState(ConnectionState.Connected);
203→      _logger.LogInformation("Connected to SignalR hub: {HubUrl}", resolvedUrl);
204→    }
205→    catch(OperationCanceledException) when(cancellationToken.IsCancellationRequested)
206→    {
207→      _logger.LogWarning("RepoService initialization was cancelled");
208→      SetConnectionState(ConnectionState.Disconnected);
209→      throw;
210→    }
211→    catch(Exception ex)
212→    {
213→      _logger.LogWarning(ex, "Failed to connect to SignalR hub: {HubUrl}. Repo will work offline.", resolvedUrl);
214→      SetConnectionState(ConnectionState.Disconnected);
215→    }
216→  }
