224→  public async Task<List<string>> ListServerDocumentsAsync()
225→  {
226→    ThrowIfDisposed();
227→
228→    if(_hubConnection is null || _connectionState != ConnectionState.Connected)
229→      throw new InvalidOperationException("Cannot list server documents: not connected to hub.");
230→
231→    _logger.LogDebug("Requesting document list from server hub");
232→    return await _hubConnection.InvokeAsync<List<string>>("ListDocuments");
