251→  void OnDocumentPeersChanged(object? sender, DocumentPeersChangedEventArgs e)
252→  {
253→    int count = e.Peers.Count;
254→    int previous = Interlocked.Exchange(ref _documentPeerCount, count);
255→
256→    if(previous != count)
257→    {
258→      _logger.LogInformation(
259→        "Document peer count changed: DocumentId={DocumentId}, PeerCount={PeerCount}",
260→        e.DocumentId, count);
261→      DocumentPeerCountChanged?.Invoke(this, count);
262→    }
263→  }
264→
265→  void OnPeerConnected(object? sender, PeerEventArgs e)
266→  {
267→    int count = Interlocked.Increment(ref _peerCount);
268→    _logger.LogInformation("Peer connected: {PeerId}. Total peers: {PeerCount}", e.PeerId, count);
269→    PeerCountChanged?.Invoke(this, count);
270→  }
271→
272→  void OnPeerDisconnected(object? sender, PeerEventArgs e)
273→  {
274→    int count = Interlocked.Add(ref _peerCount, -1);
275→    if(count < 0)
276→    {
277→      Interlocked.Exchange(ref _peerCount, 0);
278→      count = 0;
279→    }
280→
281→    _logger.LogInformation("Peer disconnected: {PeerId}. Total peers: {PeerCount}", e.PeerId, count);
282→    PeerCountChanged?.Invoke(this, count);
283→  }
284→
285→  void SetConnectionState(ConnectionState state)
286→  {
287→    if(_connectionState == state)
288→      return;
289→
290→    _connectionState = state;
291→    _logger.LogInformation("Connection state changed to: {State}", state);
292→    ConnectionStateChanged?.Invoke(this, state);
293→  }
