295→  /// <inheritdoc />
296→  public void Dispose()
297→  {
298→    if(_disposed)
299→    {
300→      return;
301→    }
302→
303→    _disposed = true;
304→
305→    if(_repo is not null)
306→    {
307→      _repo.PeerConnected -= OnPeerConnected;
308→      _repo.PeerDisconnected -= OnPeerDisconnected;
309→      _repo.Dispose();
310→    }
311→
312→    if(_networkAdapter is not null)
313→    {
314→      _networkAdapter.DocumentPeersChanged -= OnDocumentPeersChanged;
315→      _networkAdapter.Dispose();
316→    }
317→
318→    _connectionService?.Dispose();
319→    _storage?.Dispose();
320→  }
321→
322→  void ThrowIfDisposed()
323→  {
324→    ObjectDisposedException.ThrowIf(_disposed, this);
325→  }
