327→  /// <summary>
328→  /// Resolves the server base URL from Aspire service discovery environment variables.
329→  /// Falls back to <c>https://localhost:5001</c> if no env vars are set.
330→  /// </summary>
331→  static string ResolveServerBaseUrl()
332→  {
333→    string? baseUrl = Environment.GetEnvironmentVariable("services__api__https__0")
334→      ?? Environment.GetEnvironmentVariable("services__api__http__0");
335→
336→    if(!string.IsNullOrEmpty(baseUrl))
337→    {
338→      return baseUrl.TrimEnd('/');
339→    }
340→
341→    // Fallback to HUB_BASE_URL env var or default
342→    string? hubBaseUrl = Environment.GetEnvironmentVariable("HUB_BASE_URL");
343→    if(!string.IsNullOrEmpty(hubBaseUrl))
344→    {
345→      return hubBaseUrl.TrimEnd('/');
346→    }
347→
348→    return "https://localhost:5001";
349→  }
