 176→  /// <summary>
 177→  /// Disposes the repository and releases all resources.
 178→  /// </summary>
 179→  public void Dispose()
 180→  {
 181→    if(_isDisposed) return;
 182→
 183→    _isDisposed = true;
 184→
 185→    // Cancel all pending saves
 186→    _saveLock.Wait();
 187→    try
 188→    {
 189→      foreach(var cts in _pendingSaves.Values)
 190→      {
 191→        cts.Cancel();
 192→        cts.Dispose();
 193→      }
 194→
 195→      _pendingSaves.Clear();
 196→    }
 197→    finally
 198→    {
 199→      _saveLock.Release();
 200→    }
 201→
 202→    // Dispose synchronizer
 203→    _synchronizer.Dispose();
 204→
 205→    // Dispose network subsystem
 206→    _network.Dispose();
 207→
 208→    // Dispose storage subsystem
 209→    _storage?.Dispose();
 210→
 211→    // Dispose all handles
 212→
 213→    _handleLock.Wait();
 214→    try
 215→    {
 216→      foreach(var handle in _handleCache.Values)
 217→      {
 218→        handle.Dispose();
 219→      }
 220→
 221→      _handleCache.Clear();
 222→
 223→      // Dispose fallback document locks created for document discovery
 224→      foreach(var fallbackLock in _documentLockFallbacks.Values)
 225→      {
 226→        fallbackLock.Dispose();
 227→      }
 228→
 229→      _documentLockFallbacks.Clear();
 230→    }
 231→    finally
 232→    {
 233→      _handleLock.Release();
 234→    }
 235→
 236→    // Dispose locks
 237→    _handleLock.Dispose();
 238→    _saveLock.Dispose();
 239→  }
