 262→  /// <summary>
 263→  /// Creates a new document with optional initial value.
 264→  /// Uses default document ID generation (not the idFactory).
 265→  /// For custom ID generation via idFactory, use CreateAsync{T}().
 266→  /// </summary>
 267→  /// <typeparam name="T">The document content type.</typeparam>
 268→  /// <param name="initialValue">Optional initial value for the document.</param>
 269→  /// <returns>A task that resolves to a handle to the newly created document.</returns>
 270→  public async Task<DocHandle<T>> Create<T>(T? initialValue = default)
 271→  {
 272→    ThrowIfDisposed();
 273→
 274→    // Generate document ID using default generator (not idFactory)
 275→    // idFactory is async, so it's handled in CreateAsync() instead
 276→    var documentId = DocumentId.Generate();
 277→
 278→    // Validate document ID
 279→    if(!DocumentId.IsValid(documentId))
 280→    {
 281→      throw new ArgumentException($"Invalid document ID: {documentId}");
 282→    }
 283→
 284→    DocHandle<T> handle;
 285→
 286→    await _handleLock.WaitAsync().ConfigureAwait(false);
 287→    try
 288→    {
 289→      // Check if already exists
 290→      if(_handleCache.ContainsKey(documentId))
 291→      {
 292→        throw new InvalidOperationException($"Document already exists: {documentId}");
 293→      }
 294→
 295→      // Create document
 296→      var doc = AutomergeDocument.Create();
 297→
 298→      // Create handle
 299→      handle = new DocHandle<T>(
 300→        documentId,
 301→        new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 302→        doc,
 303→        CreateDocHandleLogger<T>());
 304→
 305→      // Cache handle
 306→      _handleCache[documentId] = handle;
 307→    }
 308→    finally
 309→    {
 310→      _handleLock.Release();
 311→    }
 312→
 313→    // Register outside the lock to prevent deadlocks
 314→    // (RegisterHandle → synchronizer.AddDocument → docSync.BeginSync → GetDocument callback → _handleLock)
 315→    await RegisterHandle(documentId, handle).ConfigureAwait(false);
 316→
 317→    // Emit event
 318→    DocumentLoaded?.Invoke(this,
 319→      new DocumentEventArgs { DocumentId = documentId, Handle = handle });
 320→
 321→    return handle;
 322→  }
