 462→  #region Document Lifecycle - Find
 463→
 464→  /// <summary>
 465→  /// Finds an existing document, loading from storage or requesting from network.
 466→  /// </summary>
 467→  /// <typeparam name="T">The document content type.</typeparam>
 468→  /// <param name="documentId">The document ID to find.</param>
 469→  /// <param name="timeout">Optional timeout for loading. Default: 10 seconds.</param>
 470→  /// <returns>
 471→  /// A <see cref="DocHandle{T}"/> if the document exists or was loaded successfully, or null if the document
 472→  /// does not exist and could not be loaded from the network within the timeout period.
 473→  /// </returns>
 474→  /// <exception cref="ArgumentException">Thrown if document ID is invalid.</exception>
 475→  public async Task<DocHandle<T>?> Find<T>(string documentId, TimeSpan? timeout = null)
 476→  {
 477→    if(string.IsNullOrWhiteSpace(documentId))
 478→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 479→
 480→    if(!DocumentId.IsValid(documentId))
 481→      throw new ArgumentException($"Invalid document ID: {documentId}", nameof(documentId));
 482→
 483→    var documentIdValue = DocumentId.Parse(documentId);
 484→
 485→    ThrowIfDisposed();
 486→
 487→    timeout ??= TimeSpan.FromSeconds(10);
 488→
 489→    await _handleLock.WaitAsync().ConfigureAwait(false);
 490→    bool lockHeld = true;
 491→    Task<IDocHandle>? findTask;
 492→    try
 493→    {
 494→      // Check cache first
 495→      if(_handleCache.TryGetValue(documentId, out var cachedHandle))
 496→      {
 497→        return (DocHandle<T>)cachedHandle;
 498→      }
 499→
 500→      // Check if find already in progress
 501→      if(_findInProgress.TryGetValue(documentId, out findTask))
 502→      {
 503→        // Release lock before awaiting another find to avoid holding it long-term
 504→        _handleLock.Release();
 505→        lockHeld = false;
 506→        var result = await findTask.ConfigureAwait(false);
 507→        return (DocHandle<T>)result;
 508→      }
 509→
 510→      // Start new find operation
 511→      var tcs = new TaskCompletionSource<IDocHandle>();
 512→      _findInProgress[documentId] = tcs.Task;
 513→      findTask = tcs.Task;
 514→    }
 515→    finally
 516→    {
 517→      if(lockHeld)
 518→        _handleLock.Release();
 519→    }
 520→
 521→    try
 522→    {
 523→      // Attempt to load from storage first
 524→      AutomergeDocument? doc = null;
 525→      if(_storage is not null)
 526→      {
 527→        doc = await _storage.LoadDoc(documentId).ConfigureAwait(false);
 528→      }
 529→
 530→      // Create handle (without document - we'll initialize explicitly)
 531→      var handle = new DocHandle<T>(
 532→        documentId,
 533→        new DocHandleOptions<T> { IsNew = false, ViewFactory = CreateViewFactory<T>(), Timeout = timeout.Value },
 534→        document: null,
 535→        logger: CreateDocHandleLogger<T>());
 536→
 537→      // Cache handle
 538→      await _handleLock.WaitAsync().ConfigureAwait(false);
 539→      try
 540→      {
 541→        _handleCache[documentId] = handle;
 542→        _findInProgress.Remove(documentId);
 543→
 544→        // Complete the TaskCompletionSource
 545→        if(findTask is Task<IDocHandle> task &&
 546→           task.AsyncState is TaskCompletionSource<IDocHandle> taskSource)
 547→        {
 548→          taskSource.SetResult(handle);
 549→        }
 550→      }
 551→      finally
 552→      {
 553→        _handleLock.Release();
 554→      }
 555→
 556→      // Begin lifecycle: Idle → Loading
 557→      handle.Begin();
 558→
 559→      // Split into two paths based on whether a document was loaded from storage
 560→      if(doc is not null)
 561→      {
 562→        // PATH A: Document found in storage
 563→        // Initialize the handle with the loaded document
 564→        handle.Initialize(doc, isNewDocument: false);
 565→        handle.DoneLoading();  // Loading → Ready
 566→
 567→        // Now register with subsystems
 568→        await RegisterHandle(documentId, handle).ConfigureAwait(false);
 569→
 570→        // Emit loaded event
 571→        DocumentLoaded?.Invoke(this,
 572→          new DocumentEventArgs { DocumentId = documentIdValue, Handle = handle });
 573→
 574→        return handle;  // Already ready, return immediately
 575→      }
 576→      else
 577→      {
 578→        // PATH B: Document must be loaded from network (or created if unavailable)
 579→        // Wait for network to be ready before requesting
 580→        await _network.WhenReady().ConfigureAwait(false);
 581→
 582→        // Transition to requesting state: Loading → Requesting
 583→        handle.Request();
 584→
 585→        // Now register with subsystems (synchronizer sees Requesting state)
 586→        await RegisterHandle(documentId, handle).ConfigureAwait(false);
 587→
 588→        // Wait for the handle to be ready (or timeout)
 589→        using var cts = new CancellationTokenSource(timeout.Value);
 590→        try
 591→        {
 592→          await handle.WhenReadyAsync(cts.Token).ConfigureAwait(false);
 593→          return handle;  // Document loaded successfully from network
 594→        }
 595→        catch(OperationCanceledException)
 596→        {
 597→          // Timeout: document not available from network
 598→          // Return null to indicate document doesn't exist
 599→          // Caller should use Create() to create a new document
 600→          return null;
 601→        }
 602→      }
 603→    }
 604→    catch(Exception ex)
 605→    {
 606→      _logger.LogError(ex, "Find failed [DocumentId={DocumentId}]", documentId);
 607→      // Clean up on error
 608→      await _handleLock.WaitAsync().ConfigureAwait(false);
 609→      try
 610→      {
 611→        _findInProgress.Remove(documentId);
 612→      }
 613→      finally
 614→      {
 615→        _handleLock.Release();
 616→      }
 617→
 618→      throw;
 619→    }
 620→  }
 621→
 622→  #endregion
