 624→  #region Document Lifecycle - Delete, Clone, Import, Export
 625→
 626→  /// <summary>
 627→  /// Deletes a document from the repository.
 628→  /// </summary>
 629→  /// <param name="documentId">The document ID to delete.</param>
 630→  public async Task Delete(string documentId)
 631→  {
 632→    if(string.IsNullOrWhiteSpace(documentId))
 633→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 634→
 635→    ThrowIfDisposed();
 636→
 637→    IDocHandle? handle;
 638→
 639→    await _handleLock.WaitAsync().ConfigureAwait(false);
 640→    try
 641→    {
 642→      if(!_handleCache.TryGetValue(documentId, out handle))
 643→      {
 644→        return;
 645→      }
 646→
 647→      _handleCache.Remove(documentId);
 648→    }
 649→    finally
 650→    {
 651→      _handleLock.Release();
 652→    }
 653→
 654→    // Unregister from subsystems
 655→    await _synchronizer.RemoveDocument(documentId).ConfigureAwait(false);
 656→
 657→    // Mark handle as deleted
 658→    handle.Delete();
 659→
 660→    // Emit event
 661→    DocumentDeleted?.Invoke(this, new DocumentDeletedEventArgs { DocumentId = handle.DocumentId });
 662→
 663→    // Fire-and-forget storage deletion to maintain sync API
 664→    if(_storage is not null)
 665→    {
 666→      _ = Task.Run(async () =>
 667→      {
 668→        try
 669→        {
 670→          await _storage.RemoveDoc(documentId).ConfigureAwait(false);
 671→        }
 672→        catch(Exception ex)
 673→        {
 674→          _logger.LogError(ex, "Delete: storage removal failed [DocumentId={DocumentId}]", documentId);
 675→        }
 676→      });
 677→    }
 678→  }
