 680→  /// <summary>
 681→  /// Creates a new document as a clone of an existing document.
 682→  /// </summary>
 683→  /// <typeparam name="T">The document content type.</typeparam>
 684→  /// <param name="source">The source handle to clone.</param>
 685→  /// <returns>A task that resolves to a handle to the cloned document.</returns>
 686→  public async Task<DocHandle<T>> Clone<T>(DocHandle<T> source)
 687→  {
 688→    if(source is null)
 689→      throw new ArgumentNullException(nameof(source));
 690→
 691→    ThrowIfDisposed();
 692→
 693→    // Generate new document ID
 694→    var newDocumentId = _idFactory is not null
 695→      ? DocumentId.FromBinary(await _idFactory(Array.Empty<string>()).ConfigureAwait(false))
 696→      : DocumentId.Generate();
 697→
 698→    // Clone the underlying document
 699→    var sourceDocHandle = source;
 700→    var sourceDoc = sourceDocHandle.Doc();
 701→    var clonedDocBytes = (sourceDoc as AutomergeDocument)!.Save();
 702→    var clonedDoc = AutomergeDocument.Load(clonedDocBytes);
 703→
 704→    // Create new handle
 705→    var handle = new DocHandle<T>(
 706→      newDocumentId,
 707→      new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 708→      clonedDoc,
 709→      CreateDocHandleLogger<T>());
 710→
 711→    await _handleLock.WaitAsync().ConfigureAwait(false);
 712→    try
 713→    {
 714→      _handleCache[newDocumentId] = handle;
 715→    }
 716→    finally
 717→    {
 718→      _handleLock.Release();
 719→    }
 720→
 721→    // Register outside the lock to prevent deadlocks
 722→    await RegisterHandle(newDocumentId, handle).ConfigureAwait(false);
 723→
 724→    // Emit event
 725→    DocumentLoaded?.Invoke(this,
 726→      new DocumentEventArgs { DocumentId = newDocumentId, Handle = handle });
 727→
 728→    return handle;
 729→  }
 730→
 731→  /// <summary>
 732→  /// Exports a document as binary data.
 733→  /// </summary>
 734→  /// <param name="documentId">The document ID to export.</param>
 735→  /// <returns>The binary representation of the document, or null if not found.</returns>
 736→  public async Task<byte[]?> Export(string documentId)
 737→  {
 738→    if(string.IsNullOrWhiteSpace(documentId))
 739→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 740→
 741→    ThrowIfDisposed();
 742→
 743→    // Try to get from cache first
 744→    await _handleLock.WaitAsync().ConfigureAwait(false);
 745→    IDocHandle? handle;
 746→    try
 747→    {
 748→      if(!_handleCache.TryGetValue(documentId, out handle))
 749→      {
 750→        // Not in cache, try loading from storage
 751→        if(_storage is not null)
 752→        {
 753→          var doc = await _storage.LoadDoc(documentId).ConfigureAwait(false);
 754→          if(doc is not null)
 755→          {
 756→            return doc.Save();
 757→          }
 758→        }
 759→
 760→        return null;
 761→      }
 762→    }
 763→    finally
 764→    {
 765→      _handleLock.Release();
 766→    }
 767→
 768→    // Export from handle
 769→    var document = handle.GetDocument();
 770→    return document!.Save();
 771→  }
 772→
 773→  /// <summary>
 774→  /// Imports a document from binary data.
 775→  /// </summary>
 776→  /// <typeparam name="T">The document content type.</typeparam>
 777→  /// <param name="data">The binary data to import.</param>
 778→  /// <param name="documentId">Optional document ID. If null, a new ID is generated.</param>
 779→  /// <returns>A task that resolves to a handle to the imported document.</returns>
 780→  public async Task<DocHandle<T>> Import<T>(byte[] data, string? documentId = null)
 781→  {
 782→    if(data is null || data.Length == 0)
 783→      throw new ArgumentException("Data cannot be null or empty", nameof(data));
 784→
 785→    ThrowIfDisposed();
 786→
 787→    // Load document from binary
 788→    var doc = AutomergeDocument.Load(data);
 789→
 790→    // Generate or validate document ID
 791→    if(documentId is null)
 792→    {
 793→      // Extract ID from document heads
 794→      var heads = doc.GetHeads();
 795→      documentId = _idFactory is not null
 796→        ? DocumentId.FromBinary(await _idFactory(heads).ConfigureAwait(false))
 797→        : DocumentId.Generate();
 798→    }
 799→    else if(!DocumentId.IsValid(documentId))
 800→    {
 801→      throw new ArgumentException($"Invalid document ID: {documentId}", nameof(documentId));
 802→    }
 803→
 804→    // Create handle
 805→    var handle = new DocHandle<T>(
 806→      documentId,
 807→      new DocHandleOptions<T> { IsNew = false, ViewFactory = CreateViewFactory<T>() },
 808→      doc,
 809→      CreateDocHandleLogger<T>());
 810→
 811→    await _handleLock.WaitAsync().ConfigureAwait(false);
 812→    try
 813→    {
 814→      // Check if already exists
 815→      if(_handleCache.ContainsKey(documentId))
 816→      {
 817→        throw new InvalidOperationException($"Document already exists: {documentId}");
 818→      }
 819→
 820→      _handleCache[documentId] = handle;
 821→    }
 822→    finally
 823→    {
 824→      _handleLock.Release();
 825→    }
 826→
 827→    // Register outside the lock to prevent deadlocks
 828→    await RegisterHandle(documentId, handle).ConfigureAwait(false);
 829→
 830→    // Emit event
 831→    DocumentLoaded?.Invoke(this,
 832→      new DocumentEventArgs { DocumentId = DocumentId.Parse(documentId), Handle = handle });
 833→
 834→    return handle;
 835→  }
