 904→  #region Throttled Save
 905→
 906→  /// <summary>
 907→  /// Schedules a throttled save for a document.
 908→  /// </summary>
 909→  async Task ScheduleSave(string documentId)
 910→  {
 911→    if(_storage is null) return;
 912→
 913→    await _saveLock.WaitAsync().ConfigureAwait(false);
 914→    try
 915→    {
 916→      // Cancel existing pending save
 917→      if(_pendingSaves.TryGetValue(documentId, out var existingCts))
 918→      {
 919→        existingCts.Cancel();
 920→        existingCts.Dispose();
 921→      }
 922→
 923→      // Schedule new save after debounce period
 924→      var cts = new CancellationTokenSource();
 925→      _pendingSaves[documentId] = cts;
 926→
 927→      _ = Task.Delay(_saveDebounceRate, cts.Token)
 928→        .ContinueWith(async _ =>
 929→        {
 930→          if(cts.IsCancellationRequested) return;
 931→
 932→          await PerformSave(documentId).ConfigureAwait(false);
 933→
 934→          await _saveLock.WaitAsync().ConfigureAwait(false);
 935→          try
 936→          {
 937→            _pendingSaves.Remove(documentId);
 938→            cts.Dispose();
 939→          }
 940→          finally
 941→          {
 942→            _saveLock.Release();
 943→          }
 944→        }, TaskScheduler.Default);
 945→    }
 946→    finally
 947→    {
 948→      _saveLock.Release();
 949→    }
 950→  }
 951→
 952→  /// <summary>
 953→  /// Performs the actual save operation.
 954→  /// </summary>
 955→  async Task PerformSave(string documentId)
 956→  {
 957→    if(_storage is null) return;
 958→
 959→    await _handleLock.WaitAsync().ConfigureAwait(false);
 960→    IDocHandle? handle;
 961→    try
 962→    {
 963→      if(!_handleCache.TryGetValue(documentId, out handle))
 964→      {
 965→        return; // Document no longer exists
 966→      }
 967→    }
 968→    finally
 969→    {
 970→      _handleLock.Release();
 971→    }
 972→
 973→    var doc = handle.GetDocument();
 974→    if(doc is not null)
 975→    {
 976→      await _storage.SaveDoc(documentId, doc).ConfigureAwait(false);
 977→    }
 978→  }
