1066→  /// <summary>
1067→  /// Callback for synchronizer to get the document lock for serializing FFI access.
1068→  /// Returns the handle's lock if available, otherwise a per-document fallback lock
1069→  /// for documents being discovered or not yet loaded.
1070→  /// </summary>
1071→  SemaphoreSlim GetDocumentLock(string documentId)
1072→  {
1073→    _handleLock.Wait();
1074→    try
1075→    {
1076→      if(_handleCache.TryGetValue(documentId, out var handle))
1077→      {
1078→        return handle.DocumentLock;
1079→      }
1080→
1081→      // Return a stable fallback lock for documents not yet in the handle cache
1082→      // (e.g., during discovery when a sync message arrives before the handle is created).
1083→      if(!_documentLockFallbacks.TryGetValue(documentId, out var fallback))
1084→      {
1085→        fallback = new SemaphoreSlim(1, 1);
1086→        _documentLockFallbacks[documentId] = fallback;
1087→      }
1088→
1089→      return fallback;
1090→    }
1091→    finally
1092→    {
1093→      _handleLock.Release();
1094→    }
1095→  }
