1101→  /// to release the lock before calling RegisterHandle.
1102→  /// </summary>
1103→  AutomergeDocument? GetDocument(string documentId)
1104→  {
1105→    _handleLock.Wait();
1106→    try
1107→    {
1108→      if(_handleCache.TryGetValue(documentId, out var handle))
1109→      {
1110→        return handle.GetDocument();
1111→      }
1112→
1113→      return null;
1114→    }
1115→    finally
1116→    {
1117→      _handleLock.Release();
1118→    }
1119→  }
