1248→  /// <summary>
1249→  /// Flushes pending saves for specified documents (or all documents).
1250→  /// </summary>
1251→  /// <param name="documentIds">Optional list of document IDs to flush. If null, flushes all.</param>
1252→  public async Task Flush(IEnumerable<string>? documentIds = null)
1253→  {
1254→    if(_storage is null) return;
1255→
1256→    ThrowIfDisposed();
1257→
1258→    var idsToFlush = documentIds?.ToList() ?? _handleCache.Keys.ToList();
1259→
1260→    var saveTasks = new List<Task>();
1261→
1262→    foreach(var documentId in idsToFlush)
1263→    {
1264→      // Cancel pending throttled save
1265→      await _saveLock.WaitAsync().ConfigureAwait(false);
1266→      try
1267→      {
1268→        if(_pendingSaves.TryGetValue(documentId, out var cts))
1269→        {
1270→          cts.Cancel();
1271→          _pendingSaves.Remove(documentId);
1272→        }
1273→      }
1274→      finally
1275→      {
1276→        _saveLock.Release();
1277→      }
1278→
1279→      // Perform immediate save
1280→      saveTasks.Add(PerformSave(documentId));
1281→    }
1282→
1283→    await Task.WhenAll(saveTasks).ConfigureAwait(false);
1284→  }
1285→
1286→  /// <summary>
1287→  /// Removes a document from the cache without deleting from storage.
1288→  /// Useful for memory management.
1289→  /// </summary>
1290→  /// <param name="documentId">The document ID to remove from cache.</param>
1291→  public async Task RemoveFromCache(string documentId)
1292→  {
1293→    if(string.IsNullOrWhiteSpace(documentId))
1294→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
1295→
1296→    ThrowIfDisposed();
1297→
1298→    // Flush first
1299→    await Flush(new[] { documentId }).ConfigureAwait(false);
1300→
1301→    await _handleLock.WaitAsync().ConfigureAwait(false);
1302→    IDocHandle? handle;
1303→    try
1304→    {
1305→      if(!_handleCache.TryGetValue(documentId, out handle))
1306→      {
1307→        return;
1308→      }
1309→
1310→      _handleCache.Remove(documentId);
1311→    }
1312→    finally
1313→    {
1314→      _handleLock.Release();
1315→    }
1316→
1317→    // Unregister from synchronizer
1318→    await _synchronizer.RemoveDocument(documentId).ConfigureAwait(false);
1319→
1320→    // Unload handle
1321→    handle.Unload();
1322→  }
