1324→  /// <summary>
1325→  /// Gracefully shuts down the repository, flushing all pending saves.
1326→  /// </summary>
1327→  public async Task Shutdown()
1328→  {
1329→    if(_isDisposed) return;
1330→
1331→    // Flush all documents
1332→    await Flush().ConfigureAwait(false);
1333→
1334→    // Dispose
1335→    Dispose();
1336→  }
