 95→  /// <exception cref="ArgumentNullException">Thrown if data is null.</exception>
 96→  public async Task Save(string @namespace, string key, byte[] data)
 97→  {
 98→    ThrowIfDisposed();
 99→
100→    if(string.IsNullOrWhiteSpace(@namespace))
101→      throw new ArgumentException("Namespace cannot be null or whitespace.", nameof(@namespace));
102→    if(string.IsNullOrWhiteSpace(key))
103→      throw new ArgumentException("Key cannot be null or whitespace.", nameof(key));
104→    if(data is null)
