344→  /// <summary>
345→  /// Determines if document storage should be compacted.
346→  /// Compaction replaces snapshot + incrementals with a single new snapshot.
347→  /// </summary>
348→  /// <param name="documentId">The document identifier.</param>
349→  /// <returns>True if compaction should occur; false otherwise.</returns>
350→  async Task<bool> ShouldCompact(string documentId)
351→  {
352→    var prefix = new StorageKey(new[] { documentId });
353→    var chunks = await _adapter.GetChunkInfo(prefix);
354→
355→    var snapshotSize = chunks
356→      .Where(c => c.Type == ChunkType.Snapshot)
357→      .Sum(c => c.Size);
358→
359→    var incrementalSize = chunks
360→      .Where(c => c.Type == ChunkType.Incremental)
361→      .Sum(c => c.Size);
362→
363→    // Compact when incrementals are as large as snapshot
364→    // Also compact if there's no snapshot yet (first save)
365→    return snapshotSize == 0 || incrementalSize >= snapshotSize;
366→  }
