368→  /// <summary>
369→  /// Compacts storage by saving a new full snapshot and removing old chunks.
370→  /// </summary>
371→  /// <param name="documentId">The document identifier.</param>
372→  /// <param name="doc">The document to save.</param>
373→  async Task CompactStorage(string documentId, AutomergeDocument doc)
374→  {
375→    // Save full snapshot
376→    byte[] snapshotData;
377→    try
378→    {
379→      snapshotData = doc.Save();
380→    }
381→    catch(Exception ex)
382→    {
383→      throw new InvalidOperationException($"Failed to save snapshot for document '{documentId}'.", ex);
384→    }
385→
386→    // Generate snapshot key using current heads
387→    var currentHeads = doc.GetHeads();
388→    var headHash = currentHeads.Count > 0 ? currentHeads[0] : "empty";
389→    var snapshotKey = StorageKey.DocumentSnapshot(documentId, headHash);
390→
391→    // Remove old chunks first (all chunks for this document except sync states)
392→    var prefix = new StorageKey(new[] { documentId });
393→    var existingChunks = await _adapter.LoadRange(prefix);
394→
395→    // Remove snapshots and incrementals, but keep sync states
396→    foreach(var chunk in existingChunks)
397→    {
398→      if(chunk.Type == ChunkType.Snapshot || chunk.Type == ChunkType.Incremental)
399→      {
400→        await _adapter.Remove(chunk.Key);
401→      }
402→    }
403→
404→    // Save new snapshot
405→    await _adapter.Save(snapshotKey, snapshotData);
406→  }
