  1→using Microsoft.Extensions.Caching.Memory;
  2→using Six.Automerge.Repository.Storage;
  3→
  4→namespace Six.Automerge.Repository.Storage.FileSystem;
  5→
  6→/// <summary>
  7→/// File system storage adapter that persists data to local disk with in-memory caching.
  8→/// </summary>
  9→/// <remarks>
 10→/// <para>
 11→/// This adapter stores data in a hierarchical directory structure with sharding to prevent
 12→/// directory overflow. The first key component is split: first 2 chars become a directory,
 13→/// remaining chars become a subdirectory.
 14→/// </para>
 15→/// <para>
 16→/// Example: Key ["abc123", "snapshot", "hash"] → baseDir/ab/c123/snapshot/hash
 17→/// </para>
 18→/// <para>
 19→/// Data is cached in memory using MemoryCache for fast repeated reads.
 20→/// </para>
 21→/// </remarks>
 22→[PublicAPI]
 23→public sealed class FileSystemStorageAdapter : StorageAdapterBase, IDisposable
 24→{
 25→  readonly string _baseDirectory;
 26→  readonly IMemoryCache _cache;
 27→  readonly HashSet<string> _cacheKeys = [];
 28→  readonly SemaphoreSlim _lock = new(1, 1);
 29→  readonly TimeSpan _cacheSlidingExpiration;
 30→  bool _disposed;
 31→
 32→
 33→  /// <summary>
 34→  /// Creates a new file system storage adapter.
 35→  /// </summary>
 36→  /// <param name="baseDirectory">Base directory for storage. Created if it doesn't exist.</param>
 37→  /// <param name="options">Optional configuration. If null, uses default settings.</param>
 38→  public FileSystemStorageAdapter(string baseDirectory, FileSystemStorageOptions? options = null)
 39→  {
 40→    if(string.IsNullOrWhiteSpace(baseDirectory))
 41→      throw new ArgumentException("Base directory cannot be null or whitespace", nameof(baseDirectory));
 42→
 43→    options ??= new FileSystemStorageOptions();
 44→
 45→    _baseDirectory = Path.GetFullPath(baseDirectory);
 46→    _cacheSlidingExpiration = options.CacheSlidingExpiration;
 47→
 48→    // Initialize cache with size limit
 49→    _cache = new MemoryCache(new MemoryCacheOptions
 50→    {
 51→      SizeLimit = options.CacheSizeLimit
 52→    });
 53→
 54→    // Create base directory if it doesn't exist
 55→    Directory.CreateDirectory(_baseDirectory);
 56→  }
 57→
 58→
 59→  /// <summary>
 60→  /// Loads data for a storage key. Checks cache first, then disk.
 61→  /// </summary>
 62→  public override async Task<byte[]?> Load(StorageKey key)
 63→  {
 64→    ThrowIfDisposed();
 65→
 66→    await _lock.WaitAsync();
 67→    try
 68→    {
 69→      return await LoadCore(key);
 70→    }
 71→    finally
 72→    {
 73→      _lock.Release();
 74→    }
 75→  }
 76→
 77→
 78→  /// <summary>
 79→  /// Loads data for a storage key without acquiring the lock.
 80→  /// Checks cache first, then reads from disk and populates cache.
 81→  /// </summary>
 82→  /// <remarks>
 83→  /// Callers must hold <see cref="_lock"/> before calling this method.
 84→  /// This exists so <see cref="LoadRange"/> can call it from within its own lock scope
 85→  /// without causing a deadlock.
 86→  /// </remarks>
 87→  async Task<byte[]?> LoadCore(StorageKey key)
 88→  {
 89→    var cacheKey = GetCacheKey(key);
 90→
 91→    // Try cache first
 92→    if(_cache.TryGetValue(cacheKey, out byte[]? cachedData))
 93→    {
 94→      return cachedData;
 95→    }
 96→
 97→    // Load from disk
 98→    var filePath = GetFilePath(key);
 99→
100→    try
101→    {
102→      if(!File.Exists(filePath))
103→        return null;
104→
105→      var data = await File.ReadAllBytesAsync(filePath);
106→
107→      // Store in cache with sliding expiration
108→      var cacheOptions = new MemoryCacheEntryOptions()
109→        .SetSize(data.Length)
110→        .SetSlidingExpiration(_cacheSlidingExpiration);
111→
112→      _cache.Set(cacheKey, data, cacheOptions);
113→
114→      // Track cache key for prefix-based eviction
115→      _cacheKeys.Add(cacheKey);
116→
117→      return data;
118→    }
119→    catch(FileNotFoundException)
120→    {
121→      return null;
122→    }
123→    catch(DirectoryNotFoundException)
124→    {
125→      return null;
126→    }
127→  }
128→
129→  /// <summary>
130→  /// Saves data to storage. Updates cache and writes to disk.
131→  /// </summary>
132→  public override async Task Save(StorageKey key, byte[] data)
133→  {
134→    ThrowIfDisposed();
135→
136→    if(data == null)
137→      throw new ArgumentNullException(nameof(data));
138→
139→    var cacheKey = GetCacheKey(key);
140→    var filePath = GetFilePath(key);
141→
142→    await _lock.WaitAsync();
143→    try
144→    {
145→      // Create directory structure
146→      var directory = Path.GetDirectoryName(filePath);
147→      if(!string.IsNullOrEmpty(directory))
148→      {
149→        Directory.CreateDirectory(directory);
150→      }
151→
152→      // Write to disk
153→      await File.WriteAllBytesAsync(filePath, data);
154→
155→      // Update cache
156→      var cacheOptions = new MemoryCacheEntryOptions()
157→        .SetSize(data.Length)
158→        .SetSlidingExpiration(_cacheSlidingExpiration);
159→
160→      _cache.Set(cacheKey, data, cacheOptions);
161→
162→      // Track cache key for prefix-based eviction
163→      _cacheKeys.Add(cacheKey);
164→    }
165→    finally
166→    {
167→      _lock.Release();
168→    }
169→  }
