200→  /// <summary>
201→  /// Loads all chunks matching a key prefix. Combines cached and disk data.
202→  /// </summary>
203→  public override async Task<IReadOnlyList<Chunk>> LoadRange(StorageKey keyPrefix)
204→  {
205→    ThrowIfDisposed();
206→
207→    var dirPath = GetFilePath(keyPrefix);
208→    var results = new Dictionary<string, Chunk>(); // Use dict to deduplicate
209→
210→    await _lock.WaitAsync();
211→    try
212→    {
213→      // Walk directory tree to find all files
214→      var diskFiles = await WalkDirectory(dirPath);
215→
216→      // Load each file (will hit cache if available)
217→      foreach(var filePath in diskFiles)
218→      {
219→        // Convert file path back to StorageKey
220→        var relativePath = Path.GetRelativePath(_baseDirectory, filePath);
221→        var components = ParseFilePathToKey(relativePath);
222→        var storageKey = new StorageKey(components);
223→
224→        // Check if key matches prefix
225→        if(storageKey.StartsWith(keyPrefix))
226→        {
227→          // Load data without re-acquiring lock (hits cache if present)
228→          var data = await LoadCore(storageKey);
229→          if(data != null)
230→          {
231→            var keyString = storageKey.ToDebugString();
232→            results[keyString] = new Chunk(storageKey, data);
233→          }
234→        }
235→      }
236→
237→      return results.Values.ToList();
238→    }
239→    finally
240→    {
241→      _lock.Release();
242→    }
243→  }
