328→  /// <summary>
329→  /// Converts a storage key to a file system path using directory sharding.
330→  /// </summary>
331→  /// <remarks>
332→  /// The first key component is split into two parts for sharding:
333→  /// - First 2 characters become a directory (prevents too many files in one dir)
334→  /// - Remaining characters become a subdirectory
335→  /// - Other components are appended as subdirectories
336→  ///
337→  /// Example: ["abc123def", "snapshot", "hash456"]
338→  /// → baseDir/ab/c123def/snapshot/hash456
339→  /// </remarks>
340→  string GetFilePath(StorageKey key)
341→  {
342→    if(key.Components.Count == 0)
343→      throw new ArgumentException("StorageKey must have at least one component");
344→
345→    var firstKey = key.Components[0];
346→    if(firstKey.Length < 2)
347→      throw new ArgumentException($"First key component must be at least 2 chars: {firstKey}");
348→
349→    // Shard: first 2 chars / remaining chars / other components
350→    var shardDir = firstKey[..2];         // First 2 chars
351→    var remaining = firstKey[2..];         // Rest of first key
352→
353→    var pathComponents = new List<string> { _baseDirectory, shardDir, remaining };
354→    pathComponents.AddRange(key.Components.Skip(1));
355→
356→    return Path.Combine(pathComponents.ToArray());
357→  }
358→
359→
360→  /// <summary>
361→  /// Gets the cache key for a storage key (uses ToDebugString for consistency).
362→  /// </summary>
363→  string GetCacheKey(StorageKey key) => key.ToDebugString();
364→
365→
366→  /// <summary>
367→  /// Converts a relative file path back to storage key components.
368→  /// Reverses the sharding: ab/c123/snapshot/hash → ["abc123", "snapshot", "hash"]
369→  /// </summary>
370→  List<string> ParseFilePathToKey(string relativePath)
371→  {
372→    var parts = relativePath.Split(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
373→
374→    if(parts.Length < 2)
375→      throw new ArgumentException($"Invalid file path format: {relativePath}");
376→
377→    // Reconstruct first key: parts[0] + parts[1] (un-shard)
378→    var firstKey = parts[0] + parts[1];
379→
380→    var components = new List<string> { firstKey };
381→    components.AddRange(parts.Skip(2));
382→
383→    return components;
384→  }
385→
386→
387→  /// <summary>
388→  /// Recursively walks a directory and returns all file paths.
389→  /// Returns empty list if directory doesn't exist.
390→  /// </summary>
391→  async Task<List<string>> WalkDirectory(string dirPath)
392→  {
393→    var files = new List<string>();
394→
395→    if(!Directory.Exists(dirPath))
396→      return files;
397→
398→    try
399→    {
400→      // Get all files in current directory
401→      var directFiles = Directory.GetFiles(dirPath);
402→      files.AddRange(directFiles);
403→
404→      // Recursively process subdirectories
405→      var subdirectories = Directory.GetDirectories(dirPath);
406→      foreach(var subdir in subdirectories)
407→      {
408→        var subFiles = await WalkDirectory(subdir);
409→        files.AddRange(subFiles);
410→      }
411→    }
412→    catch(UnauthorizedAccessException)
413→    {
414→      // Skip directories we can't access
415→    }
416→    catch(DirectoryNotFoundException)
417→    {
418→      // Directory was deleted during traversal
419→    }
420→
421→    return files;
422→  }
423→
424→
425→  /// <summary>
426→  /// Disposes the adapter and releases resources.
427→  /// </summary>
428→  public void Dispose()
429→  {
430→    if(_disposed)
431→      return;
432→
433→    _disposed = true;
434→
435→    _cache.Dispose();
436→    _lock.Dispose();
437→  }
438→
439→
440→  /// <summary>
441→  /// Throws if the adapter has been disposed.
442→  /// </summary>
443→  void ThrowIfDisposed()
444→  {
445→    if(_disposed)
446→      throw new ObjectDisposedException(nameof(FileSystemStorageAdapter));
447→  }
448→}
