  9→namespace Six.Automerge.SyncServer;
 10→
 11→/// <summary>
 12→/// A server-side sync endpoint that manages an internal Repo for document storage
 13→/// and synchronization. Uses a passive share config (does not announce, but accepts
 14→/// all access) and bridges to an <see cref="IServerTransport"/> for external communication.
 15→/// </summary>
 16→[PublicAPI]
 17→public sealed class SyncServer : IAsyncDisposable
 18→{
 19→  readonly AutomergeRepo _repo;
 20→  readonly TransportBridgeAdapter _bridgeAdapter;
 21→  readonly DebouncedPersistence _persistence;
 22→  readonly SyncServerOptions _options;
 23→  readonly ILogger _logger;
 24→  bool _disposed;
 25→
 26→  /// <summary>
 27→  /// Creates a new sync server with the specified options and transport.
 28→  /// </summary>
 29→  /// <param name="options">Server configuration options.</param>
 30→  /// <param name="transport">The transport layer for external communication.</param>
 31→  public SyncServer(SyncServerOptions options, IServerTransport transport)
 32→  {
 33→    ArgumentNullException.ThrowIfNull(options);
 34→    ArgumentNullException.ThrowIfNull(transport);
 35→
 36→    _options = options;
 37→    _logger = options.LoggerFactory?.CreateLogger<SyncServer>()
 38→              ?? NullLoggerFactory.Instance.CreateLogger<SyncServer>();
 39→
 40→    var peerId = PeerId.Generate();
 41→    _bridgeAdapter = new TransportBridgeAdapter(transport, peerId);
 42→
 43→    _repo = new AutomergeRepo(new RepoConfig
 44→    {
 45→      PeerId = peerId,
 46→      Storage = options.Storage,
 47→      NetworkAdapters = [_bridgeAdapter],
 48→      SaveDebounceRate = options.SaveDebounceRate,
 49→      SyncDebounceRate = options.SyncDebounceRate,
 50→      ShareConfig = new ShareConfig
 51→      {
 52→        Announce = (_, _) => Task.FromResult(false),
 53→        Access = (_, _) => Task.FromResult(true)
 54→      },
 55→      LoggerFactory = options.LoggerFactory
 56→    });
 57→
 58→    _persistence = new DebouncedPersistence(_repo, options.PersistenceInterval, options.LoggerFactory);
 59→
 60→    _repo.DocumentLoaded += OnDocumentLoaded;
 61→  }
 62→
 63→  /// <summary>
 64→  /// The server's peer ID, used to identify the server in the sync protocol.
 65→  /// </summary>
 66→  public PeerId PeerId => _repo.PeerId;
 67→
 68→  /// <summary>
 69→  /// The internal Repo managed by this server. Exposed for advanced scenarios
 70→  /// such as direct document manipulation.
 71→  /// </summary>
 72→  internal AutomergeRepo Repo => _repo;
 73→
 74→  /// <summary>
 75→  /// Called by the transport layer when a peer connects.
 76→  /// </summary>
 77→  /// <param name="peerId">The connecting peer's ID.</param>
 78→  /// <param name="metadata">Optional peer metadata.</param>
 79→  public Task OnPeerConnectedAsync(PeerId peerId, PeerMetadata? metadata = null)
 80→  {
 81→    ThrowIfDisposed();
 82→    _logger.LogInformation("Peer connected: {PeerId}", peerId);
 83→    _bridgeAdapter.RaisePeerConnected(peerId, metadata);
 84→    return Task.CompletedTask;
 85→  }
 86→
 87→  /// <summary>
 88→  /// Called by the transport layer when a peer disconnects.
 89→  /// </summary>
 90→  /// <param name="peerId">The disconnecting peer's ID.</param>
 91→  public Task OnPeerDisconnectedAsync(PeerId peerId)
 92→  {
 93→    ThrowIfDisposed();
 94→    _logger.LogInformation("Peer disconnected: {PeerId}", peerId);
 95→    _bridgeAdapter.RaisePeerDisconnected(peerId);
 96→    return Task.CompletedTask;
 97→  }
 98→
 99→  /// <summary>
100→  /// Called by the transport layer when a message is received from a peer.
101→  /// </summary>
102→  /// <param name="peerId">The sending peer's ID.</param>
103→  /// <param name="message">The received message.</param>
104→  public Task OnMessageReceivedAsync(PeerId peerId, IRepoMessage message)
105→  {
106→    ThrowIfDisposed();
107→    ArgumentNullException.ThrowIfNull(message);
108→
109→    // Stamp the sender and relay to the internal Repo
110→    IRepoMessage stamped = message.WithSender(peerId);
111→    _bridgeAdapter.RaiseMessageReceived(stamped);
112→
113→    // Mark the document as dirty for periodic persistence
114→    if(message.DocumentId is { } documentId)
115→    {
116→      _persistence.MarkDirty(documentId.Value);
117→    }
118→
119→    return Task.CompletedTask;
120→  }
121→
122→  /// <summary>
123→  /// Lists all document IDs currently stored in the server's storage.
124→  /// Scans storage for snapshot chunks and returns unique document IDs.
125→  /// </summary>
126→  /// <returns>A list of document IDs found in storage.</returns>
127→  public async Task<IReadOnlyList<string>> ListDocumentsAsync()
128→  {
129→    ThrowIfDisposed();
130→
131→    // Use an empty prefix to get all chunks, then extract unique document IDs
132→    var emptyPrefix = new StorageKey(Array.Empty<string>());
133→    var chunks = await _options.Storage.GetChunkInfo(emptyPrefix).ConfigureAwait(false);
134→
135→    var documentIds = new HashSet<string>();
136→    foreach(ChunkInfo chunk in chunks)
137→    {
138→      if(chunk.Key.Components is { Count: > 0 })
139→      {
140→        documentIds.Add(chunk.Key.Components[0]);
141→      }
142→    }
143→
144→    return documentIds.ToList();
145→  }
146→
147→  /// <summary>
148→  /// Exports a document as binary data (Automerge save format).
149→  /// </summary>
150→  /// <param name="documentId">The document ID to export.</param>
151→  /// <returns>The binary document data, or null if not found.</returns>
152→  public async Task<byte[]?> ExportDocumentAsync(string documentId)
153→  {
154→    ThrowIfDisposed();
155→    return await _repo.Export(documentId).ConfigureAwait(false);
156→  }
157→
158→  /// <summary>
159→  /// Deletes a document from the server, removing it from both cache and storage.
160→  /// </summary>
161→  /// <param name="documentId">The document ID to delete.</param>
162→  public async Task DeleteDocumentAsync(string documentId)
163→  {
164→    ThrowIfDisposed();
165→    await _repo.Delete(documentId).ConfigureAwait(false);
166→
167→    // Also clean up storage directly for documents not in cache
168→    var prefix = new StorageKey(new[] { documentId });
169→    await _options.Storage.RemoveRange(prefix).ConfigureAwait(false);
170→  }
171→
172→  void OnDocumentLoaded(object? sender, DocumentEventArgs e)
173→  {
174→    _logger.LogDebug("Document loaded: {DocumentId}", e.DocumentId);
175→  }
176→
177→  void ThrowIfDisposed()
178→  {
179→    ObjectDisposedException.ThrowIf(_disposed, this);
180→  }
181→
182→  /// <summary>
183→  /// Shuts down the server, flushing all pending persistence and cleaning up resources.
184→  /// </summary>
185→  public async ValueTask DisposeAsync()
186→  {
187→    if(_disposed) return;
188→    _disposed = true;
189→
190→    _repo.DocumentLoaded -= OnDocumentLoaded;
191→
192→    await _persistence.DisposeAsync().ConfigureAwait(false);
193→    await _repo.Shutdown().ConfigureAwait(false);
194→  }
195→}
