 10→namespace Server.Api.Hubs;
 11→
 12→/// <summary>
 13→/// SignalR hub for Automerge document synchronization backed by <see cref="SyncServer"/>.
 14→/// All sync protocol messages are routed through the server's Repo, enabling the server
 15→/// to participate in document synchronization and persist documents.
 16→/// </summary>
 17→[PublicAPI]
 18→public sealed class DocumentsHub : Hub<IDocumentsHubClient>, IDocumentsHub
 19→{
 20→  readonly SyncServer _syncServer;
 21→  readonly SignalRServerTransport _transport;
 22→  readonly DocumentPeerTracker _tracker;
 23→  readonly ILogger<DocumentsHub> _logger;
 24→
 25→  public DocumentsHub(
 26→    SyncServer syncServer,
 27→    SignalRServerTransport transport,
 28→    DocumentPeerTracker tracker,
 29→    ILoggerFactory loggerFactory)
 30→  {
 31→    ArgumentNullException.ThrowIfNull(syncServer);
 32→    ArgumentNullException.ThrowIfNull(transport);
 33→    ArgumentNullException.ThrowIfNull(tracker);
 34→    ArgumentNullException.ThrowIfNull(loggerFactory);
 35→
 36→    _syncServer = syncServer;
 37→    _transport = transport;
 38→    _tracker = tracker;
 39→    _logger = loggerFactory.CreateLogger<DocumentsHub>();
 40→  }
 41→
 42→  /// <inheritdoc />
 43→  public async Task<PeerHandshakeDto> Handshake(PeerHandshakeDto handshake)
 44→  {
 45→    try
 46→    {
 47→      _logger.LogInformation(
 48→        "Peer handshake: PeerId={PeerId}, ConnectionId={ConnectionId}",
 49→        handshake.PeerId, Context.ConnectionId);
 50→
 51→      Context.Items["PeerId"] = handshake.PeerId;
 52→      Context.Items["Metadata"] = handshake.Metadata;
 53→
 54→      var peerId = new PeerId(handshake.PeerId);
 55→      var metadata = handshake.Metadata?.ToPeerMetadata();
 56→
 57→      _transport.RegisterPeer(Context.ConnectionId, peerId);
 58→      await _syncServer.OnPeerConnectedAsync(peerId, metadata);
 59→
 60→      await Clients.Others.OnPeerJoined(handshake);
 61→
 62→      return PeerHandshakeDto.Create(_syncServer.PeerId, null);
 63→    }
 64→    catch(Exception ex)
 65→    {
 66→      _logger.LogError(ex,
 67→        "Error during handshake. PeerId={PeerId}, ConnectionId={ConnectionId}",
 68→        handshake.PeerId, Context.ConnectionId);
 69→      throw;
 70→    }
 71→  }
 72→
 73→  /// <inheritdoc />
 74→  public async Task SendMessage(MessageDto message)
 75→  {
 76→    try
 77→    {
 78→      if(string.IsNullOrEmpty(message.DocumentId))
 79→      {
 80→        _logger.LogWarning(
 81→          "Received message with empty DocumentId. ConnectionId={ConnectionId}",
 82→          Context.ConnectionId);
 83→        return;
 84→      }
 85→
 86→      _logger.LogDebug(
 87→        "Routing message: DocumentId={DocumentId}, MessageType={MessageType}, SenderId={SenderId}",
 88→        message.DocumentId, message.MessageType, message.SenderId);
 89→
 90→      await Groups.AddToGroupAsync(Context.ConnectionId, message.DocumentId);
 91→
 92→      // Track peer presence on this document
 93→      var peerInfo = BuildPeerInfo();
 94→      if(peerInfo is not null)
 95→      {
 96→        _tracker.AddPeerToDocument(message.DocumentId, peerInfo.Value);
 97→        await BroadcastDocumentPeersAsync(message.DocumentId);
 98→      }
 99→
100→      var repoMessage = DeserializeMessage(message);
101→      if(repoMessage is not null)
102→      {
103→        var senderId = new PeerId(message.SenderId);
104→        await _syncServer.OnMessageReceivedAsync(senderId, repoMessage);
105→      }
106→    }
107→    catch(Exception ex)
108→    {
109→      _logger.LogError(ex,
110→        "Error routing message. DocumentId={DocumentId}, ConnectionId={ConnectionId}",
111→        message.DocumentId, Context.ConnectionId);
112→    }
113→  }
114→
115→  /// <inheritdoc />
116→  public async Task SubscribeToDocument(string documentId)
117→  {
118→    try
119→    {
120→      if(string.IsNullOrEmpty(documentId))
121→      {
122→        _logger.LogWarning("Subscribe with empty documentId. ConnectionId={ConnectionId}",
123→          Context.ConnectionId);
124→        return;
125→      }
126→
127→      await Groups.AddToGroupAsync(Context.ConnectionId, documentId);
128→
129→      // Track peer presence on this document
130→      var peerInfo = BuildPeerInfo();
131→      if(peerInfo is not null)
132→      {
133→        _tracker.AddPeerToDocument(documentId, peerInfo.Value);
134→        await BroadcastDocumentPeersAsync(documentId);
135→      }
136→
137→      _logger.LogInformation(
138→        "Client subscribed: DocumentId={DocumentId}, ConnectionId={ConnectionId}",
139→        documentId, Context.ConnectionId);
140→    }
141→    catch(Exception ex)
142→    {
143→      _logger.LogError(ex,
144→        "Error subscribing. DocumentId={DocumentId}, ConnectionId={ConnectionId}",
145→        documentId, Context.ConnectionId);
146→    }
147→  }
148→
149→  /// <inheritdoc />
150→  public async Task UnsubscribeFromDocument(string documentId)
151→  {
152→    try
153→    {
154→      if(string.IsNullOrEmpty(documentId))
155→      {
156→        _logger.LogWarning("Unsubscribe with empty documentId. ConnectionId={ConnectionId}",
157→          Context.ConnectionId);
158→        return;
159→      }
160→
161→      await Groups.RemoveFromGroupAsync(Context.ConnectionId, documentId);
162→
163→      _logger.LogInformation(
164→        "Client unsubscribed: DocumentId={DocumentId}, ConnectionId={ConnectionId}",
165→        documentId, Context.ConnectionId);
166→    }
167→    catch(Exception ex)
168→    {
169→      _logger.LogError(ex,
170→        "Error unsubscribing. DocumentId={DocumentId}, ConnectionId={ConnectionId}",
171→        documentId, Context.ConnectionId);
172→    }
173→  }
174→
175→  /// <inheritdoc />
176→  public Task<List<PeerInfoDto>> GetDocumentPeers(string documentId)
177→  {
178→    var callerPeerId = Context.Items.TryGetValue("PeerId", out var id) ? id?.ToString() : null;
179→    return Task.FromResult(_tracker.GetDocumentPeers(documentId, callerPeerId));
180→  }
181→
182→  /// <inheritdoc />
183→  public Task<int> GetDocumentPeerCount(string documentId)
184→  {
185→    var callerPeerId = Context.Items.TryGetValue("PeerId", out var id) ? id?.ToString() : null;
186→    return Task.FromResult(_tracker.GetDocumentPeerCount(documentId, callerPeerId));
187→  }
188→
189→  /// <summary>
190→  /// Returns the list of document IDs stored in the SyncServer.
191→  /// </summary>
192→  public async Task<List<string>> ListDocuments()
193→  {
194→    try
195→    {
196→      var docs = await _syncServer.ListDocumentsAsync();
197→      _logger.LogDebug("Listed {Count} documents", docs.Count);
198→      return docs.ToList();
199→    }
200→    catch(Exception ex)
201→    {
202→      _logger.LogError(ex, "Error listing documents");
203→      return [];
204→    }
205→  }
206→
207→  /// <inheritdoc />
208→  public override Task OnConnectedAsync()
209→  {
210→    _logger.LogInformation("Client connected: ConnectionId={ConnectionId}", Context.ConnectionId);
211→    return base.OnConnectedAsync();
212→  }
213→
214→  /// <inheritdoc />
215→  public override async Task OnDisconnectedAsync(Exception? exception)
216→  {
217→    var peerIdStr = Context.Items.TryGetValue("PeerId", out var id) ? id?.ToString() : null;
218→
219→    if(exception is not null)
220→    {
221→      _logger.LogWarning(exception,
222→        "Client disconnected with error: ConnectionId={ConnectionId}, PeerId={PeerId}",
223→        Context.ConnectionId, peerIdStr ?? "unknown");
224→    }
225→    else
226→    {
227→      _logger.LogInformation(
228→        "Client disconnected: ConnectionId={ConnectionId}, PeerId={PeerId}",
229→        Context.ConnectionId, peerIdStr ?? "unknown");
230→    }
231→
232→    if(!string.IsNullOrEmpty(peerIdStr))
233→    {
234→      // Remove peer from tracker and broadcast updated peer lists
235→      var affectedDocuments = _tracker.RemovePeerFromAllDocuments(peerIdStr);
236→      foreach(var documentId in affectedDocuments)
237→      {
238→        await BroadcastDocumentPeersAsync(documentId);
239→      }
240→
241→      var peerId = new PeerId(peerIdStr);
242→      _transport.UnregisterPeer(Context.ConnectionId);
243→      await _syncServer.OnPeerDisconnectedAsync(peerId);
244→      await Clients.Others.OnPeerLeft(peerIdStr);
245→    }
246→
247→    await base.OnDisconnectedAsync(exception);
248→  }
249→
250→  /// <summary>
251→  /// Broadcasts the updated peer list for a document to all clients in the group.
252→  /// Each client receives a list that excludes their own entry.
253→  /// </summary>
254→  async Task BroadcastDocumentPeersAsync(string documentId)
255→  {
256→    // Broadcast to all peers in the group — each gets a list excluding themselves.
257→    // Use Clients.Group to send to all (including caller), since each peer gets
258→    // the full list and can filter if needed. For per-client exclusion, we send
259→    // the full list and rely on the interface contract that says "excluding the
260→    // receiving client's own entry" — we use OthersInGroup for the broadcast
261→    // and send separately to the caller.
262→    var callerPeerId = Context.Items.TryGetValue("PeerId", out var id) ? id?.ToString() : null;
263→
264→    // Send to others in group (full peer list — they don't know who "caller" is so we send all)
265→    var allPeers = _tracker.GetDocumentPeers(documentId);
266→    await Clients.OthersInGroup(documentId).OnDocumentPeersChanged(documentId, allPeers);
267→
268→    // Send to caller with their own entry excluded
269→    if(callerPeerId is not null)
270→    {
271→      var peersForCaller = _tracker.GetDocumentPeers(documentId, callerPeerId);
272→      await Clients.Caller.OnDocumentPeersChanged(documentId, peersForCaller);
273→    }
274→  }
275→
276→  PeerInfoDto? BuildPeerInfo()
277→  {
278→    if(!Context.Items.TryGetValue("PeerId", out var id) || id is not string peerId)
279→      return null;
280→
281→    var metadata = Context.Items.TryGetValue("Metadata", out var meta) ? meta as PeerMetadataDto? : null;
282→
283→    return new PeerInfoDto
284→    {
285→      PeerId = peerId,
286→      Metadata = metadata
287→    };
288→  }
289→
290→  static IRepoMessage? DeserializeMessage(MessageDto messageDto)
291→  {
292→    var senderId = new PeerId(messageDto.SenderId);
293→
294→    return messageDto.MessageType switch
295→    {
296→      "sync" => new SyncMessage
297→      {
298→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
299→        Data = messageDto.Data,
300→        SenderId = senderId
301→      },
302→      "request" => new RequestMessage
303→      {
304→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
305→        Data = messageDto.Data,
306→        SenderId = senderId
307→      },
308→      "doc-unavailable" => new DocumentUnavailableMessage
309→      {
310→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
311→        SenderId = senderId
312→      },
313→      "doc-snapshot" => new DocumentSnapshotMessage
314→      {
315→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
316→        Data = messageDto.Data ?? [],
317→        SenderId = senderId
318→      },
319→      _ => null
320→    };
321→  }
322→}
