  7→/// <summary>
  8→/// High-level wrapper around an Automerge text CRDT that provides
  9→/// cached text/formatting state, debounced change application,
 10→/// and events for text and formatting changes.
 11→/// </summary>
 12→[PublicAPI]
 13→public sealed class TextDocument : IDisposable
 14→{
 15→  readonly DocHandle<object> _handle;
 16→  readonly TextDocumentOptions _options;
 17→  readonly AutomergeObjectId _textObjectId;
 18→  readonly SemaphoreSlim _refreshLock = new(1, 1);
 19→
 20→  ChangeDebouncer? _debouncer;
 21→  string _cachedText = string.Empty;
 22→  FormattedText _cachedFormattedText = new([]);
 23→  bool _isLocalChange;
 24→  bool _isDisposed;
 25→
 26→  public event EventHandler<TextChangedEventArgs>? TextChanged;
 27→  public event EventHandler<FormattedTextChangedEventArgs>? FormattedTextChanged;
