260→  public void Dispose()
261→  {
262→    if(_isDisposed)
263→    {
264→      return;
265→    }
266→
267→    _isDisposed = true;
268→
269→    if(_options.AutoFlushOnDispose && _debouncer is not null)
270→    {
271→      // Best-effort flush — fire and forget since Dispose is synchronous
272→      try
273→      {
274→        _debouncer.FlushAsync().GetAwaiter().GetResult();
275→      }
276→      catch(ObjectDisposedException)
277→      {
278→        // Handle already disposed
279→      }
280→    }
281→
282→    _handle.Changed -= OnDocHandleChanged;
283→    _debouncer?.Dispose();
284→    _refreshLock.Dispose();
285→  }
286→
287→  async Task FlushTextChangeAsync(string newText)
288→  {
289→    string currentText = _cachedText;
290→    var splice = TextDiff.ComputeSplice(currentText, newText);
291→
292→    if(!splice.HasChanges)
293→    {
294→      return;
295→    }
296→
297→    _isLocalChange = true;
298→    try
299→    {
300→      await _handle.ChangeAsync(
301→        doc => doc.SpliceText(
302→          _textObjectId,
303→          (ulong)splice.Offset,
304→          splice.DeleteCount,
305→          splice.InsertText)).ConfigureAwait(false);
306→    }
307→    finally
308→    {
309→      _isLocalChange = false;
310→    }
311→
312→    await RefreshFromDocumentAsync(CancellationToken.None).ConfigureAwait(false);
313→    TextChanged?.Invoke(this, new TextChangedEventArgs(_cachedText, true));
314→  }
315→
316→  void OnDocHandleChanged(object? sender, DocHandleChangeEventArgs<object> e)
317→  {
318→    if(_isDisposed || _isLocalChange)
319→    {
320→      return;
321→    }
322→
323→    _ = HandleRemoteChangeAsync();
324→  }
325→
326→  async Task HandleRemoteChangeAsync()
327→  {
328→    try
329→    {
330→      await RefreshFromDocumentAsync(CancellationToken.None).ConfigureAwait(false);
331→      TextChanged?.Invoke(this, new TextChangedEventArgs(_cachedText, false));
332→      FormattedTextChanged?.Invoke(this, new FormattedTextChangedEventArgs(_cachedFormattedText, false));
333→    }
334→    catch(ObjectDisposedException)
335→    {
336→      // Handle was disposed during async operation
337→    }
338→  }
339→
340→  async Task RefreshFromDocumentAsync(CancellationToken cancellationToken)
341→  {
342→    await _refreshLock.WaitAsync(cancellationToken).ConfigureAwait(false);
343→    try
344→    {
345→      var textId = _textObjectId;
346→
347→      var (text, spans) = await _handle.ReadAsync(
348→        doc =>
349→        {
350→          string t = doc.GetText(textId);
351→          var s = doc.GetSpans(textId);
352→          return (t, s);
353→        },
354→        cancellationToken).ConfigureAwait(false);
355→
356→      Volatile.Write(ref _cachedText, text);
357→      Volatile.Write(ref _cachedFormattedText, FormattedText.FromSpans(spans));
358→    }
359→    finally
360→    {
361→      _refreshLock.Release();
362→    }
363→  }
364→
365→  void EnsureNotDisposed()
366→  {
367→    ObjectDisposedException.ThrowIf(_isDisposed, this);
368→  }
369→}
