  4→namespace Six.Automerge.Repo.Network.SignalR;
  5→
  6→/// <summary>
  7→/// SignalR-based network adapter for Automerge document synchronization.
  8→/// </summary>
  9→/// <remarks>
 10→/// This adapter provides real-time collaborative editing over ASP.NET Core SignalR with:
 11→/// <list type="bullet">
 12→///   <item><description>Automatic reconnection and connection lifecycle management</description></item>
 13→///   <item><description>MessagePack serialization with LZ4 compression for bandwidth efficiency</description></item>
 14→///   <item><description>Document-based group subscriptions for targeted message delivery</description></item>
 15→///   <item><description>Thread-safe operations with concurrent access support</description></item>
 16→/// </list>
 17→///
 18→/// <para>
 19→/// <strong>Usage Example:</strong>
 20→/// <code>
 21→/// var adapter = new SignalRNetworkAdapter(connectionService, loggerFactory);
 22→/// adapter.MessageReceived += (sender, args) => {
 23→///   Console.WriteLine($"Received: {args.Message.MessageType}");
 24→/// };
 25→/// adapter.Connect(PeerId.Generate(), null);
 26→/// await adapter.WhenReady();
 27→/// adapter.Send(syncMessage);
 28→/// </code>
 29→/// </para>
 30→/// </remarks>
 31→[PublicAPI]
 32→public sealed class SignalRNetworkAdapter : INetworkAdapter, IDocumentsHubClient, IDisposable, IAsyncDisposable
 33→{
 34→  readonly ISignalRConnectionService _connectionService;
 35→  readonly ILogger<SignalRNetworkAdapter> _logger;
 36→  readonly string _adapterId;
 37→  readonly SemaphoreSlim _lock = new(1, 1);
 38→  readonly TaskCompletionSource _readyTcs = new();
 39→  readonly ConcurrentDictionary<string, byte> _subscribedDocuments = new();
 40→
 41→  HubConnection? _connection;
 42→  PeerId? _peerId;
 43→  bool _isReady;
 44→  bool _disposed;
 45→
 46→  /// <summary>
 47→  /// Initializes a new instance of the <see cref="SignalRNetworkAdapter"/> class.
 48→  /// </summary>
 49→  /// <param name="connectionService">The SignalR connection service.</param>
 50→  /// <param name="loggerFactory">The logger factory.</param>
 51→  public SignalRNetworkAdapter(
 52→    ISignalRConnectionService connectionService,
 53→    ILoggerFactory loggerFactory)
 54→  {
 55→    _connectionService = connectionService ?? throw new ArgumentNullException(nameof(connectionService));
 56→    ArgumentNullException.ThrowIfNull(loggerFactory);
 57→
 58→    _logger = loggerFactory.CreateLogger<SignalRNetworkAdapter>();
 59→    _adapterId = $"signalr-{Guid.NewGuid():N}";
 60→  }
 61→
 62→  /// <inheritdoc />
 63→  public string AdapterId => _adapterId;
 64→
 65→  /// <inheritdoc />
 66→  public bool IsReady => _isReady;
 67→
 68→  /// <inheritdoc />
 69→  public Task WhenReady() => _readyTcs.Task;
 70→
 71→  /// <inheritdoc />
 72→  public event EventHandler<PeerCandidateEventArgs>? PeerCandidate;
 73→
 74→  /// <inheritdoc />
 75→  public event EventHandler<PeerDisconnectedEventArgs>? PeerDisconnected;
 76→
 77→  /// <inheritdoc />
 78→  public event EventHandler<MessageReceivedEventArgs>? MessageReceived;
 79→
 80→  /// <inheritdoc />
 81→  public event EventHandler? Closed;
 82→
 83→  /// <summary>
 84→  /// Raised when the server notifies that the peer list for a document has changed.
 85→  /// </summary>
 86→  public event EventHandler<DocumentPeersChangedEventArgs>? DocumentPeersChanged;
 87→
 88→  /// <inheritdoc />
 89→  public void Connect(PeerId peerId, PeerMetadata? metadata = null)
 90→  {
 91→    if (_disposed)
 92→      throw new ObjectDisposedException(nameof(SignalRNetworkAdapter));
 93→
 94→    _ = ConnectAsyncInternal(peerId, metadata);
 95→  }
 96→
 97→  async Task ConnectAsyncInternal(PeerId peerId, PeerMetadata? metadata)
 98→  {
 99→    await _lock.WaitAsync();
100→    try
101→    {
102→      if (_isReady)
103→      {
104→        _logger.LogWarning("Adapter already connected. Ignoring duplicate Connect call.");
105→        return;
106→      }
107→
108→      _logger.LogInformation("Connecting SignalR adapter for peer: {PeerId}", peerId);
109→      _peerId = peerId;
110→
111→      // Get connection from service
112→      _connection = await _connectionService.GetConnection();
113→      _logger.LogDebug("SignalR connection established. ConnectionId={ConnectionId}", _connection.ConnectionId ?? "<pending>");
114→
115→      // Register client methods for hub callbacks
116→      _logger.LogDebug("Registering hub callbacks for connection {ConnectionId}", _connection.ConnectionId ?? "<pending>");
117→      _connection.On<MessageDto>(
118→        "OnReceiveMessage",
119→        msg =>
120→        {
121→          _logger.LogTrace("Hub invoked OnReceiveMessage. DocumentId={DocumentId}, MessageType={MessageType}, SenderId={SenderId}",
122→            msg.DocumentId,
123→            msg.MessageType,
124→            msg.SenderId);
125→          _ = ((IDocumentsHubClient)this).OnReceiveMessage(msg);
126→        });
127→      _connection.On<PeerHandshakeDto>(
128→        "OnPeerJoined",
129→        handshake =>
130→        {
131→          _logger.LogTrace("Hub invoked OnPeerJoined for PeerId={PeerId}", handshake.PeerId);
132→          _ = ((IDocumentsHubClient)this).OnPeerJoined(handshake);
133→        });
134→      _connection.On<string>(
135→        "OnPeerLeft",
136→        peerId =>
137→        {
138→          _logger.LogTrace("Hub invoked OnPeerLeft for PeerId={PeerId}", peerId);
139→          _ = ((IDocumentsHubClient)this).OnPeerLeft(peerId);
140→        });
141→      _connection.On<string, List<PeerInfoDto>>(
142→        "OnDocumentPeersChanged",
143→        (documentId, peers) =>
144→        {
145→          _logger.LogTrace("Hub invoked OnDocumentPeersChanged for DocumentId={DocumentId}, PeerCount={PeerCount}", documentId, peers.Count);
146→          _ = ((IDocumentsHubClient)this).OnDocumentPeersChanged(documentId, peers);
147→        });
148→
149→      // Hook connection lifecycle events
150→      _connection.Closed += OnConnectionClosedAsync;

