 3→namespace Six.Automerge.TextEdit;
 4→
 5→/// <summary>
 6→/// Computes minimal splice operations between two text strings.
 7→/// Uses a prefix/suffix matching algorithm optimised for single-point edits
 8→/// typical of text editor input.
 9→/// </summary>
10→[PublicAPI]
11→public static class TextDiff
12→{
13→  /// <summary>
14→  /// Compares <paramref name="oldText"/> and <paramref name="newText"/>,
15→  /// returning a single splice that transforms old into new.
16→  /// </summary>
17→  public static SpliceResult ComputeSplice(string oldText, string newText)
18→  {
19→    ArgumentNullException.ThrowIfNull(oldText);
20→    ArgumentNullException.ThrowIfNull(newText);
21→
22→    int prefixLen = 0;
23→    int minLen = Math.Min(oldText.Length, newText.Length);
24→
25→    while(prefixLen < minLen && oldText[prefixLen] == newText[prefixLen])
26→    {
27→      prefixLen++;
28→    }
29→
30→    int suffixLen = 0;
31→    int maxSuffix = minLen - prefixLen;
32→
33→    while(suffixLen < maxSuffix
34→      && oldText[oldText.Length - 1 - suffixLen] == newText[newText.Length - 1 - suffixLen])
35→    {
36→      suffixLen++;
37→    }
38→
39→    int deleteCount = oldText.Length - prefixLen - suffixLen;
40→    string insertText = newText.Substring(prefixLen, newText.Length - prefixLen - suffixLen);
41→
42→    return new SpliceResult(prefixLen, deleteCount, insertText);
43→  }
44→}
45→
46→/// <summary>
47→/// The result of a text diff splice computation.
48→/// </summary>
49→[PublicAPI]
50→public readonly record struct SpliceResult(int Offset, int DeleteCount, string InsertText)
51→{
52→  /// <summary>
53→  /// Gets a value indicating whether this splice represents an actual change.
54→  /// </summary>
55→  public bool HasChanges => DeleteCount > 0 || InsertText.Length > 0;
56→
57→  public override string ToString() =>
58→    HasChanges
59→      ? $"Splice(offset={Offset}, delete={DeleteCount}, insert=\"{InsertText}\")"
60→      : "Splice(no change)";
61→}
