193→  async Task SendAsyncInternal(IRepoMessage message)
194→  {
195→    await _lock.WaitAsync();
196→    try
197→    {
198→      if (!_isReady || _connection is null)
199→      {
200→        _logger.LogWarning("Cannot send message: adapter not ready or connection is null");
201→        return;
202→      }
203→
204→      var documentId = message.DocumentId;
205→
206→      if (documentId is null)
207→      {
208→        _logger.LogWarning("Cannot send message: DocumentId is null or empty");
209→        return;
210→      }
211→
212→      if (_peerId is null)
213→      {
214→        _logger.LogWarning("Cannot send message type {MessageType}: adapter has no peer ID assigned", message.MessageType);
215→        return;
216→      }
217→
218→      // Auto-subscribe to document if not already subscribed
219→      var documentIdValue = documentId.Value;
220→      var documentIdString = documentIdValue.Value;
221→
222→      if (!_subscribedDocuments.ContainsKey(documentIdString))
223→      {
224→        _logger.LogDebug("Auto-subscribing to document: {DocumentId}", documentIdString);
225→        await SubscribeToDocumentInternalAsync(documentIdString);
226→      }
227→
228→      var messageWithSender = EnsureSender(message, _peerId.Value);
229→
230→      if (messageWithSender.SenderId is null && messageWithSender is DocumentSnapshotMessage snapshotWithoutSender)
231→      {
232→        messageWithSender = snapshotWithoutSender with { SenderId = _peerId.Value };
233→      }
234→
235→      _logger.LogInformation(
236→        "Sending {MessageType} message for document {DocumentId} via SignalR connection {ConnectionId} as sender {SenderId}",
237→        messageWithSender.MessageType,
238→        messageWithSender.DocumentId?.Value,
239→        _connection.ConnectionId ?? "<pending>",
240→        messageWithSender.SenderId?.ToString());
241→
242→      // Create MessageDto
243→      var messageData = GetMessageData(messageWithSender);
244→      var messageDto = MessageDto.FromRepoMessage(messageWithSender, messageData!);
245→
246→      // Send to hub
247→      await _connection.InvokeAsync("SendMessage", messageDto);
248→
249→      _logger.LogInformation("Hub accepted {MessageType} message for document {DocumentId} on connection {ConnectionId}",
250→        messageWithSender.MessageType,
251→        messageWithSender.DocumentId?.Value,
252→        _connection.ConnectionId ?? "<pending>");
253→    }
254→    catch (Exception ex)
255→    {
256→      _logger.LogError(ex, "Failed to send message type {MessageType} for document {DocumentId}",
257→        message.MessageType, message.DocumentId?.Value);
258→    }
259→    finally
260→    {
261→      _lock.Release();
262→    }
263→  }
