263→  /// Rebuilds the <see cref="AllDocuments"/> collection by merging
264→  /// <see cref="StoredDocuments"/> and <see cref="ServerDocuments"/>.
265→  /// </summary>
266→  public void RefreshAllDocuments()
267→  {
268→    AllDocuments.Clear();
269→
270→    HashSet<string> localSet = new(StoredDocuments, StringComparer.Ordinal);
271→    HashSet<string> serverSet = new(ServerDocuments, StringComparer.Ordinal);
272→    HashSet<string> seen = new(StringComparer.Ordinal);
273→
274→    // Add local documents first
275→    foreach(string docId in StoredDocuments)
276→    {
277→      if(!seen.Add(docId))
278→      {
279→        continue;
280→      }
281→
282→      DocumentSource source = serverSet.Contains(docId) ? DocumentSource.Both : DocumentSource.Local;
283→      AllDocuments.Add(new DocumentEntry(docId, source));
284→    }
285→
286→    // Add server-only documents
287→    foreach(string docId in ServerDocuments)
288→    {
289→      if(!seen.Add(docId))
290→      {
291→        continue;
292→      }
293→
294→      AllDocuments.Add(new DocumentEntry(docId, DocumentSource.Server));
295→    }
296→
297→    OnPropertyChanged(nameof(AllDocuments));
298→  }
