 3→/// <summary>
 4→/// Represents a chunk of data retrieved from storage.
 5→/// </summary>
 6→[PublicAPI]
 7→public sealed record Chunk(StorageKey Key, byte[] Data)
 8→{
 9→  /// <summary>
10→  /// Gets the type of this chunk based on its storage key.
11→  /// </summary>
12→  public ChunkType Type => ChunkTypeFromKey(Key);
13→
14→  /// <summary>
15→  /// Determines the chunk type from a storage key.
16→  /// </summary>
17→  /// <param name="key">The storage key to analyze.</param>
18→  /// <returns>The chunk type.</returns>
19→  /// <exception cref="ArgumentException">Thrown if the key format is invalid.</exception>
20→  public static ChunkType ChunkTypeFromKey(StorageKey key)
21→  {
22→    if(key.Components == null || key.Components.Count < 2)
23→    {
24→      throw new ArgumentException("Invalid storage key format: must have at least 2 components", nameof(key));
25→    }
26→
27→    return key.Components[1] switch
28→    {
29→      "snapshot" => ChunkType.Snapshot,
30→      "incremental" => ChunkType.Incremental,
31→      "sync-state" => ChunkType.SyncState,
32→      _ => throw new ArgumentException($"Unknown chunk type: {key.Components[1]}", nameof(key))
33→    };
34→  }
35→}

