  6→/// <summary>
  7→/// Manages synchronization for a single document across multiple peers.
  8→/// Maintains per-peer sync state and implements the Automerge sync protocol.
  9→/// </summary>
 10→internal sealed partial class DocSynchronizer : IDisposable
 11→{
 12→  readonly string _documentId;
 13→  readonly DocumentId _documentIdValue;
 14→  readonly Func<AutomergeDocument?> _getDocument;
 15→  readonly Func<AutomergeDocument, Task> _updateDocument;
 16→  readonly Func<PeerId, PeerMetadata?> _getPeerMetadata;
 17→  readonly Func<SemaphoreSlim?> _getDocumentLock;
 18→  readonly int _syncDebounceRate;
 19→  readonly ILogger<DocSynchronizer> _logger;
 20→
 21→  readonly Dictionary<PeerId, AutomergeSyncState> _syncStates = [];
 22→  readonly Dictionary<PeerId, PeerDocumentStatus> _peerStatuses = [];
 23→  readonly HashSet<PeerId> _activePeers = [];
 24→  readonly SemaphoreSlim _lock = new(1, 1);
 25→  readonly Throttle<PeerId>? _syncThrottle;
 26→
 27→  int _messagesSent;
 28→  int _messagesReceived;
 29→  bool _disposed;
