 46→  /// <summary>
 47→  /// Creates a new DocSynchronizer for a specific document.
 48→  /// </summary>
 49→  /// <param name="documentId">The document ID being synchronized</param>
 50→  /// <param name="getDocument">Callback to retrieve the current document</param>
 51→  /// <param name="updateDocument">Async callback to update the document after receiving changes</param>
 52→  /// <param name="getPeerMetadata">Callback to retrieve peer metadata</param>
 53→  /// <param name="getDocumentLock">Callback to retrieve the document lock for serializing FFI access</param>
 54→  /// <param name="logger">Logger for diagnostics and tracing</param>
 55→  /// <param name="syncDebounceRate">Debounce rate in milliseconds for sync message sending on local changes. 0 disables throttling.</param>
 56→  public DocSynchronizer(
 57→    string documentId,
 58→    Func<AutomergeDocument?> getDocument,
 59→    Func<AutomergeDocument, Task> updateDocument,
 60→    Func<PeerId, PeerMetadata?> getPeerMetadata,
 61→    Func<SemaphoreSlim?> getDocumentLock,
 62→    ILogger<DocSynchronizer> logger,
 63→    int syncDebounceRate = 0)
 64→  {
 65→    _documentId = documentId ?? throw new ArgumentNullException(nameof(documentId));
 66→    _documentIdValue = DocumentId.Parse(documentId);
 67→    _getDocument = getDocument ?? throw new ArgumentNullException(nameof(getDocument));
 68→    _updateDocument = updateDocument ?? throw new ArgumentNullException(nameof(updateDocument));
 69→    _getPeerMetadata = getPeerMetadata ?? throw new ArgumentNullException(nameof(getPeerMetadata));
 70→    _getDocumentLock = getDocumentLock ?? throw new ArgumentNullException(nameof(getDocumentLock));
 71→    _syncDebounceRate = syncDebounceRate;
 72→    _logger = logger ?? throw new ArgumentNullException(nameof(logger));
 73→
 74→    if(_syncDebounceRate > 0)
 75→    {
 76→      _syncThrottle = new Throttle<PeerId>(SendThrottledSyncMessage, _syncDebounceRate);
 77→    }
 78→  }
