 80→  /// <summary>
 81→  /// Begins synchronization with a peer. Sends initial sync message.
 82→  /// </summary>
 83→  public async Task BeginSync(PeerId peerId)
 84→  {
 85→    ThrowIfDisposed();
 86→
 87→    // Collect events to fire after releasing lock
 88→    var deferredEvents = new List<Action>();
 89→
 90→    await _lock.WaitAsync().ConfigureAwait(false);
 91→    try
 92→    {
 93→      if(_activePeers.Contains(peerId))
 94→      {
 95→        return;
 96→      }
 97→
 98→      _activePeers.Add(peerId);
 99→
100→      // Initialize status as unknown
101→      if(!_peerStatuses.ContainsKey(peerId))
102→      {
103→        _peerStatuses[peerId] = PeerDocumentStatus.Unknown;
104→      }
105→
106→      // Send initial sync message
107→      await SendSyncMessage(peerId, deferredEvents).ConfigureAwait(false);
108→    }
109→    finally
110→    {
111→      _lock.Release();
112→    }
113→
114→    // Fire all deferred events after releasing the lock
115→    foreach(var eventAction in deferredEvents)
116→    {
117→      eventAction();
118→    }
119→  }
120→
121→  /// <summary>
122→  /// Ends synchronization with a peer. Cleans up state.
123→  /// </summary>
124→  public async Task EndSync(PeerId peerId)
125→  {
126→    ThrowIfDisposed();
127→
128→    await _lock.WaitAsync().ConfigureAwait(false);
129→    try
130→    {
131→      _activePeers.Remove(peerId);
132→
133→      // Dispose sync state before removing
134→      if(_syncStates.TryGetValue(peerId, out var state))
135→      {
136→        state.Dispose();
137→      }
138→
139→      _syncStates.Remove(peerId);
140→      _peerStatuses.Remove(peerId);
141→    }
142→    finally
143→    {
144→      _lock.Release();
145→    }
146→  }
