151→  public async Task<bool> HasPeer(PeerId peerId)
152→  {
153→    ThrowIfDisposed();
154→
155→    await _lock.WaitAsync().ConfigureAwait(false);
156→    try
157→    {
158→      return _activePeers.Contains(peerId);
159→    }
160→    finally
161→    {
162→      _lock.Release();
163→    }
164→  }
