166→  /// <summary>
167→  /// Gets the current status of a peer for this document.
168→  /// </summary>
169→  public async Task<PeerDocumentStatus> GetPeerStatus(PeerId peerId)
170→  {
171→    ThrowIfDisposed();
172→
173→    await _lock.WaitAsync().ConfigureAwait(false);
174→    try
175→    {
176→      return _peerStatuses.TryGetValue(peerId, out var status)
177→        ? status
178→        : PeerDocumentStatus.Unknown;
179→    }
180→    finally
181→    {
182→      _lock.Release();
183→    }
184→  }
