186→  /// <summary>
187→  /// Receives and routes a message to appropriate handler.
188→  /// </summary>
189→  public async Task ReceiveMessage(IRepoMessage message, PeerId senderId)
190→  {
191→    ThrowIfDisposed();
192→
193→    _messagesReceived++;
194→
195→    // Collect events to fire after releasing lock
196→    var deferredEvents = new List<Action>();
197→
198→    await _lock.WaitAsync().ConfigureAwait(false);
199→    try
200→    {
201→      switch(message)
202→      {
203→        case SyncMessage sync:
204→          await ReceiveSyncMessage(sync, senderId, deferredEvents).ConfigureAwait(false);
205→          break;
206→
207→        case RequestMessage request:
208→          await ReceiveRequestMessage(request, senderId, deferredEvents).ConfigureAwait(false);
209→          break;
210→
211→        case DocumentUnavailableMessage unavail:
212→          ReceiveDocumentUnavailable(unavail, senderId);
213→          break;
214→        case DocumentSnapshotMessage snapshot:
215→          await ReceiveDocumentSnapshot(snapshot, senderId).ConfigureAwait(false);
216→          break;
217→
218→        default:
219→          // Unknown message type, ignore
220→          break;
221→      }
222→    }
223→    finally
224→    {
225→      _lock.Release();
226→    }
227→
228→    // Fire all deferred events after releasing the lock
229→    foreach(var eventAction in deferredEvents)
230→    {
231→      eventAction();
232→    }
233→  }
