235→  /// <summary>
236→  /// Processes incoming sync message using Automerge sync protocol.
237→  /// </summary>
238→  private async Task ReceiveSyncMessage(SyncMessage message, PeerId senderId, List<Action> deferredEvents,
239→    bool preserveWantsStatus = false)
240→  {
241→    // Validate message data
242→    if(message.Data is null)
243→    {
244→      return;
245→    }
246→
247→    // Get document (or create empty one if we don't have it yet)
248→    var doc = _getDocument();
249→    var isNewDocument = doc is null;
250→    if(doc is null)
251→    {
252→      // We don't have the document yet, but the peer is sending us data
253→      // Create an empty document to receive the sync data
254→      doc = AutomergeDocument.Create();
255→    }
256→
257→    // Get sync state for this peer
258→    var syncState = GetOrCreateSyncState(senderId);
259→
260→    var shouldRespond = true;
261→
262→    // Apply sync message using Automerge protocol
263→    // Note: Empty messages are valid in the sync protocol (they indicate "I have nothing new")
264→    // Note: The current API mutates both doc and syncState in place
265→    if(message.Data.Length > 0)
266→    {
267→      var docLock = _getDocumentLock()
268→        ?? throw new InvalidOperationException("Document lock must not be null. Ensure the lock provider returns a valid SemaphoreSlim.");
269→
270→      LogSyncMessageReceived(_documentId, senderId.ToString(), message.Data.Length);
271→
272→      await docLock.WaitAsync().ConfigureAwait(false);
273→      LogLockAcquired("ReceiveSyncMessage", _documentId, senderId.ToString());
274→      try
275→      {
276→        doc.ReceiveSyncMessage(syncState, message.Data);
277→      }
278→      catch(Exception ex)
279→      {
280→        // Upstream automerge panics are caught by the FFI layer and surfaced as exceptions.
281→        // Log and continue so the process stays alive; the sync will retry on the next round.
282→        LogSyncError(ex, "ReceiveSyncMessage", _documentId, senderId.ToString());
283→        return;
284→      }
285→      finally
286→      {
287→        docLock.Release();
288→        LogLockReleased("ReceiveSyncMessage", _documentId, senderId.ToString());
289→      }
290→
291→      // Notify owner that document was updated AFTER releasing the document lock
292→      // to prevent deadlock (NotifyRemoteChangeAsync acquires the same lock).
293→      await _updateDocument(doc).ConfigureAwait(false);
294→    }
295→    else if(isNewDocument)
296→    {
297→      // No payload but we created a local document instance; ensure repo registers it.
298→      await _updateDocument(doc).ConfigureAwait(false);
299→      // Nothing additional to send back unless we still owe data (e.g., due to request).
300→      if(!preserveWantsStatus)

300→      if(!preserveWantsStatus)
301→      {
302→        shouldRespond = false;
303→      }
304→    }
305→
306→    // Mark peer as having the document (unless we need to preserve Wants status from RequestMessage)
307→    if(!preserveWantsStatus || _peerStatuses[senderId] != PeerDocumentStatus.Wants)
308→    {
309→      _peerStatuses[senderId] = PeerDocumentStatus.Has;
310→    }
311→
312→    // Defer sync state changed event (for persistence)
313→    var peerMetadata = _getPeerMetadata(senderId);
314→    if(peerMetadata?.StorageId is not null && !peerMetadata.IsEphemeral)
315→    {
316→      var syncStateChangedArgs = new SyncStateChangedEventArgs
317→      {
318→        DocumentId = _documentIdValue, PeerId = senderId, SyncState = syncState, StorageId = peerMetadata.StorageId
319→      };
320→      deferredEvents.Add(() => SyncStateChanged?.Invoke(this, syncStateChangedArgs));
321→    }
322→
323→    // Send response sync message immediately (immediate feedback)
324→    // Note: SendSyncMessage will add its own metrics event to deferredEvents
325→    if(shouldRespond)
326→    {
327→      await SendSyncMessage(senderId, deferredEvents).ConfigureAwait(false);
328→    }
329→  }
