331→  /// <summary>
332→  /// Processes incoming request message (peer wants the document).
333→  /// </summary>
334→  private async Task ReceiveRequestMessage(RequestMessage message, PeerId senderId, List<Action> deferredEvents)
335→  {
336→    // Mark peer as wanting the document
337→    _peerStatuses[senderId] = PeerDocumentStatus.Wants;
338→
339→    // Get document
340→    var doc = _getDocument();
341→    if(doc is null)
342→    {
343→      // We don't have it either, defer sending unavailable message
344→      var unavailMessage = new DocumentUnavailableMessage { DocumentId = _documentIdValue };
345→
346→      var messageArgs = new SyncMessageEventArgs
347→      {
348→        DocumentId = _documentIdValue, TargetPeerId = senderId, Message = unavailMessage
349→      };
350→      deferredEvents.Add(() => MessageToSend?.Invoke(this, messageArgs));
351→      return;
352→    }
353→
354→    // Process as sync message (request is just a sync with empty state)
355→    // Pass preserveWantsStatus=true to keep the Wants status we just set
356→    var syncMsg = new SyncMessage { DocumentId = message.DocumentId, Data = message.Data, SenderId = senderId };
357→
358→    await ReceiveSyncMessage(syncMsg, senderId, deferredEvents, preserveWantsStatus: true).ConfigureAwait(false);
359→  }
