372→  /// <summary>
373→  /// Applies a full document snapshot from a peer.
374→  /// </summary>
375→  private async Task ReceiveDocumentSnapshot(DocumentSnapshotMessage message, PeerId senderId)
376→  {
377→    var doc = AutomergeDocument.Load(message.Data);
378→    await _updateDocument(doc).ConfigureAwait(false);
379→    _peerStatuses[senderId] = PeerDocumentStatus.Has;
380→
381→    if(_syncStates.TryGetValue(senderId, out var existingState))
382→    {
383→      existingState.Dispose();
384→    }
385→
386→    _syncStates[senderId] = AutomergeSyncState.Create();
387→  }
