389→  /// <summary>
390→  /// Generates and sends a sync message to a peer.
391→  /// If we don't have the document, sends a RequestMessage instead.
392→  /// </summary>
393→  private async Task SendSyncMessage(PeerId peerId, List<Action> deferredEvents)
394→  {
395→    // Get document
396→    var doc = _getDocument();
397→    if(doc is null)
398→    {
399→      // We don't have the document - send a RequestMessage to request it from the peer
400→      // Create an empty sync state to generate the initial request
401→      var syncState = AutomergeSyncState.Create();
402→      var emptyDoc = AutomergeDocument.Create();
403→      var requestData = emptyDoc.GenerateSyncMessage(syncState);
404→
405→      // Dispose temporary objects
406→      syncState.Dispose();
407→
408→      // Create and defer sending the request message
409→      var requestMessage = new RequestMessage
410→      {
411→        DocumentId = _documentIdValue,
412→        Data = requestData ?? Array.Empty<byte>()
413→      };
414→
415→      _messagesSent++;
416→      var requestArgs = new SyncMessageEventArgs
417→      {
418→        DocumentId = _documentIdValue,
419→        TargetPeerId = peerId,
420→        Message = requestMessage
421→      };
422→      deferredEvents.Add(() => MessageToSend?.Invoke(this, requestArgs));
423→
424→      // Defer metrics (not complete - we're requesting)
425→      var metricsArgs = new SyncMetricsEventArgs
426→      {
427→        DocumentId = _documentIdValue,
428→        PeerId = peerId,
429→        MessagesSent = _messagesSent,
430→        MessagesReceived = _messagesReceived,
431→        IsComplete = false
432→      };
433→      deferredEvents.Add(() => MetricsUpdated?.Invoke(this, metricsArgs));
434→      return;
435→    }
436→
437→    // Get sync state for this peer
438→    var peerSyncState = GetOrCreateSyncState(peerId);
439→
440→    // Single lock scope covering both GenerateSyncMessage and the conditional Save
441→    // to ensure document consistency between the two operations.
442→    var docLock = _getDocumentLock()
443→      ?? throw new InvalidOperationException("Document lock must not be null. Ensure the lock provider returns a valid SemaphoreSlim.");
444→    byte[]? messageData;
445→    byte[]? snapshotData = null;
446→
447→    await docLock.WaitAsync().ConfigureAwait(false);
448→    LogLockAcquired("SendSyncMessage", _documentId, peerId.ToString());
449→    try
450→    {
451→      messageData = doc.GenerateSyncMessage(peerSyncState);
452→
453→      // If no sync data and peer doesn't have the document, save a full snapshot
454→      if((messageData is null || messageData.Length == 0)
455→        && (!_peerStatuses.TryGetValue(peerId, out var status) || status != PeerDocumentStatus.Has))
456→      {
457→        snapshotData = doc.Save();
458→      }
459→    }
460→    catch(Exception ex)
461→    {
462→      LogSyncError(ex, "GenerateSyncMessage", _documentId, peerId.ToString());
463→      return;
464→    }
465→    finally
466→    {
467→      docLock.Release();
468→      LogLockReleased("SendSyncMessage", _documentId, peerId.ToString());
469→    }
470→
471→    if(messageData is not null && messageData.Length > 0)
472→    {
473→      LogSyncMessageSent(_documentId, peerId.ToString(), messageData.Length);
474→    }
475→
476→    // Process results outside the document lock (but still inside _lock)
477→    if(messageData is null || messageData.Length == 0)
478→    {
479→      if(snapshotData is not null)
480→      {
481→        var snapshotMessage = new DocumentSnapshotMessage
482→        {
483→          DocumentId = _documentIdValue,
484→          Data = snapshotData
485→        };
486→
487→        if(_syncStates.TryGetValue(peerId, out var existingState))
488→        {
489→          existingState.Dispose();
490→        }
491→
492→        _syncStates[peerId] = AutomergeSyncState.Create();
493→
494→        _messagesSent++;
495→        _peerStatuses[peerId] = PeerDocumentStatus.Has;
496→
497→        var snapshotArgs = new SyncMessageEventArgs
498→        {
499→          DocumentId = _documentIdValue,
500→          TargetPeerId = peerId,
501→          Message = snapshotMessage
502→        };
503→        deferredEvents.Add(() => MessageToSend?.Invoke(this, snapshotArgs));
504→
505→        var metricsArgsSnapshot = new SyncMetricsEventArgs
506→        {
507→          DocumentId = _documentIdValue,
