436→  public async ValueTask<DocLocalChange<T>?> ChangeAsync(
437→    Action<AutomergeDocument> mutation,
438→    string? message = null,
439→    long? timestampMillis = null,
440→    CancellationToken cancellationToken = default)
441→  {
442→    ArgumentNullException.ThrowIfNull(mutation);
443→
444→    // Check if we need to initialize the document (virtual document pattern)
445→    AutomergeDocument document;
446→    var existingDoc = Volatile.Read(ref _document);
447→    if(existingDoc is null)
448→    {
449→      // Document doesn't exist yet - create it (handles the case where Find() timed out)
450→      lock(_stateGate)
451→      {
452→        if(_state == HandleState.Loading || _state == HandleState.Requesting)
453→        {
454→          var newDoc = AutomergeDocument.Create();
455→          Initialize(newDoc, isNewDocument: true);
456→          DoneLoading();
457→        }
458→      }
459→      document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
460→    }
461→    else
462→    {
463→      document = existingDoc;
464→    }
465→
466→    EnsureEditable();
467→
468→    DocLocalChange<T>? change;
469→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
470→    _logger.LogDebug("Document lock acquired for ChangeAsync [DocumentId={DocumentId}]", DocumentId);
471→    try
472→    {
473→      EnsureEditable();
474→      mutation(document);
475→      var changeHash = document.Commit(message, timestampMillis);
476→      UpdateCachedHeads(document.GetHeads());
477→
478→      if(changeHash is null)
479→      {
480→        return null;
481→      }
482→
483→      var lastChange = document.GetLastLocalChange();
484→      if(lastChange is null)
485→      {
486→        return null;
487→      }
488→
489→      var clonedChange = lastChange.ToArray();
490→      _pendingLocalChanges.Add(clonedChange);
491→      var readOnlyChange = new ReadOnlyCollection<byte[]>([clonedChange]);
492→      change = new DocLocalChange<T>(this, changeHash, readOnlyChange);
493→    }
494→    finally
495→    {
496→      _documentLock.Release();
497→      _logger.LogDebug("Document lock released for ChangeAsync [DocumentId={DocumentId}]", DocumentId);
498→    }
499→
500→    OnChanged(change, isLocal: true, null);
