504→  /// <summary>
505→  /// Makes a change to the document as if it were at the specified heads, creating a concurrent branch.
506→  /// </summary>
507→  /// <param name="heads">The heads to fork at before making the change.</param>
508→  /// <param name="mutation">The mutation to apply to the forked document.</param>
509→  /// <returns>
510→  /// A list of binary changes representing the concurrent change that was made.
511→  /// </returns>
512→  /// <remarks>
513→  /// <para>
514→  /// This method creates a fork of the document at the specified heads, applies the mutation,
515→  /// commits the change, and then merges the forked document back into the main document.
516→  /// This creates a concurrent branch in the document history.
517→  /// </para>
518→  /// <para>
519→  /// This is useful for reconciling external state that was modified independently from the document.
520→  /// For example, if you have a text editor that was modified while disconnected from the document,
521→  /// you can use ChangeAt to apply those changes as if they happened at the point when the editor
522→  /// last synced.
523→  /// </para>
524→  /// </remarks>
525→  /// <exception cref="ArgumentNullException">Thrown when heads or mutation is null.</exception>
526→  /// <exception cref="ArgumentException">Thrown when heads is empty.</exception>
527→  /// <exception cref="InvalidOperationException">Thrown when the document is not ready or is read-only.</exception>
528→  public IReadOnlyList<byte[]> ChangeAt(
529→    IReadOnlyList<string> heads,
530→    Action<AutomergeDocument> mutation)
531→  {
532→    if(heads is null)
533→    {
534→      throw new ArgumentNullException(nameof(heads));
535→    }
536→
537→    if(heads.Count == 0)
538→    {
539→      throw new ArgumentException("Heads cannot be empty.", nameof(heads));
540→    }
541→
542→    ArgumentNullException.ThrowIfNull(mutation);
