548→  async ValueTask<IReadOnlyList<byte[]>> ChangeAtAsync(
549→    IReadOnlyList<string> heads,
550→    Action<AutomergeDocument> mutation,
551→    CancellationToken cancellationToken)
552→  {
553→    var document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
554→
555→    byte[]? changeBytes;
556→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
557→    _logger.LogDebug("Document lock acquired for ChangeAtAsync [DocumentId={DocumentId}]", DocumentId);
558→    try
559→    {
560→      EnsureEditable();
561→
562→      // Fork the document at the specified heads
563→      using var forkedDoc = document.ForkAtHeads(heads);
564→
565→      // Apply the mutation to the forked document
566→      mutation(forkedDoc);
567→
568→      // Commit the changes in the forked document
569→      var changeHash = forkedDoc.Commit();
570→      if(changeHash is null)
571→      {
572→        // No changes were made, return empty
573→        return Array.Empty<byte[]>();
574→      }
575→
576→      // Get the change bytes from the forked document
577→      var lastChange = forkedDoc.GetLastLocalChange();
578→      if(lastChange is null)
579→      {
580→        return Array.Empty<byte[]>();
581→      }
582→
583→      // Merge the forked document back into the main document
584→      var mergedHashes = document.Merge(forkedDoc);
585→
586→      // Update cached heads
587→      UpdateCachedHeads(document.GetHeads());
588→
589→      changeBytes = lastChange.ToArray();
590→    }
591→    finally
592→    {
593→      _documentLock.Release();
594→      _logger.LogDebug("Document lock released for ChangeAtAsync [DocumentId={DocumentId}]", DocumentId);
595→    }
596→
597→    // Emit change event outside lock
598→    OnChanged(null, isLocal: true, new[] { changeBytes });
599→
600→    // Return the change as a single-item list
601→    return new ReadOnlyCollection<byte[]>(new[] { changeBytes });
602→  }
