 31→  public SyncServer(SyncServerOptions options, IServerTransport transport)
 32→  {
 33→    ArgumentNullException.ThrowIfNull(options);
 34→    ArgumentNullException.ThrowIfNull(transport);
 35→
 36→    _options = options;
 37→    _logger = options.LoggerFactory?.CreateLogger<SyncServer>()
 38→              ?? NullLoggerFactory.Instance.CreateLogger<SyncServer>();
 39→
 40→    var peerId = PeerId.Generate();
 41→    _bridgeAdapter = new TransportBridgeAdapter(transport, peerId);
 42→
 43→    _repo = new AutomergeRepo(new RepoConfig
 44→    {
 45→      PeerId = peerId,
 46→      Storage = options.Storage,
 47→      NetworkAdapters = [_bridgeAdapter],
 48→      SaveDebounceRate = options.SaveDebounceRate,
 49→      SyncDebounceRate = options.SyncDebounceRate,
 50→      ShareConfig = new ShareConfig
 51→      {
 52→        Announce = (_, _) => Task.FromResult(false),
 53→        Access = (_, _) => Task.FromResult(true)
 54→      },
 55→      LoggerFactory = options.LoggerFactory
 56→    });
 57→
 58→    _persistence = new DebouncedPersistence(_repo, options.PersistenceInterval, options.LoggerFactory);
 59→
 60→    _repo.DocumentLoaded += OnDocumentLoaded;
 61→  }
