  3→/// <summary>
  4→/// In-memory storage adapter for testing and ephemeral repositories.
  5→/// </summary>
  6→/// <remarks>
  7→/// This adapter stores all data in memory using a dictionary. Data is lost when the adapter
  8→/// is disposed or when the application terminates. Use this adapter for:
  9→/// <list type="bullet">
 10→/// <item>Unit and integration testing</item>
 11→/// <item>Temporary documents that don't require persistence</item>
 12→/// <item>Prototyping and development</item>
 13→/// </list>
 14→/// <para>
 15→/// This adapter is thread-safe and supports concurrent operations.
 16→/// </para>
 17→/// </remarks>
 18→[PublicAPI]
 19→public sealed class InMemoryStorageAdapter : IStorageAdapter, IDisposable
 20→{
 21→  readonly Dictionary<string, byte[]> _storage = [];
 22→  readonly SemaphoreSlim _lock = new(1, 1);
 23→  bool _isDisposed;
 24→  
 25→  
 26→  /// <summary>
 27→  /// Gets the number of keys currently stored.
 28→  /// </summary>
 29→  /// <remarks>
 30→  /// This property is useful for testing and debugging.
 31→  /// </remarks>
 32→  public int Count
 33→  {
 34→    get
 35→    {
 36→      ThrowIfDisposed();
 37→      return _storage.Count;
 38→    }
 39→  }
 40→  
 41→  
 42→  
 43→  /// <summary>
 44→  /// 
 45→  /// Disposes this storage adapter and clears all data.
 46→  /// </summary>
 47→  public void Dispose()
 48→  {
 49→    if(_isDisposed)
 50→      return;
 51→
 52→    _isDisposed = true;
 53→    _storage.Clear();
 54→    _lock.Dispose();
 55→  }
 56→
 57→  
 58→  public async Task<byte[]?> Load(StorageKey key)
 59→  {
 60→    ThrowIfDisposed();
 61→
 62→    await _lock.WaitAsync();
 63→    try
 64→    {
 65→      var keyString = key.ToDebugString();
 66→      if(!_storage.TryGetValue(keyString, out var data))
 67→        return null;
 68→
 69→      // Copy the data to ensure isolation
 70→      var copy = new byte[data.Length];
 71→      Array.Copy(data, copy, data.Length);
 72→      return copy;
 73→    }
 74→    finally
 75→    {
 76→      _lock.Release();
 77→    }
 78→  }
 79→
 80→  public async Task Save(StorageKey key, byte[] data)
 81→  {
 82→    ThrowIfDisposed();
 83→
 84→    if(data is null)
 85→      throw new ArgumentNullException(nameof(data));
 86→
 87→    await _lock.WaitAsync();
 88→    try
 89→    {
 90→      var keyString = key.ToDebugString();
 91→      // Copy the data to ensure isolation
 92→      var copy = new byte[data.Length];
 93→      Array.Copy(data, copy, data.Length);
 94→      _storage[keyString] = copy;
 95→    }
 96→    finally
 97→    {
 98→      _lock.Release();
 99→    }
100→  }
101→
102→  public async Task Remove(StorageKey key)
103→  {
104→    ThrowIfDisposed();
105→
106→    await _lock.WaitAsync();
107→    try
108→    {
109→      var keyString = key.ToDebugString();
110→      _storage.Remove(keyString);
111→    }
112→    finally
113→    {
114→      _lock.Release();
115→    }
116→  }
