118→  public async Task<IReadOnlyList<Chunk>> LoadRange(StorageKey keyPrefix)
119→  {
120→    ThrowIfDisposed();
121→
122→    await _lock.WaitAsync();
123→    try
124→    {
125→      var results = new List<Chunk>();
126→
127→      foreach(var kvp in _storage)
128→      {
129→        // Parse the key back to StorageKey
130→        var components = kvp.Key.Split('/');
131→        var storageKey = new StorageKey(components);
132→
133→        // Check if it matches the prefix
134→        if(storageKey.StartsWith(keyPrefix))
135→        {
136→          // Copy the data to ensure isolation
137→          var dataCopy = new byte[kvp.Value.Length];
138→          Array.Copy(kvp.Value, dataCopy, kvp.Value.Length);
139→          results.Add(new Chunk(storageKey, dataCopy));
140→        }
141→      }
142→
143→      return results;
144→    }
145→    finally
146→    {
147→      _lock.Release();
148→    }
149→  }
150→
151→  public async Task RemoveRange(StorageKey keyPrefix)
152→  {
153→    ThrowIfDisposed();
154→
155→    await _lock.WaitAsync();
156→    try
157→    {
158→      // Find all keys that match the prefix
159→      var keysToRemove = new List<string>();
160→
161→      foreach(var kvp in _storage)
162→      {
163→        var components = kvp.Key.Split('/');
164→        var storageKey = new StorageKey(components);
165→
166→        if(storageKey.StartsWith(keyPrefix))
167→        {
168→          keysToRemove.Add(kvp.Key);
169→        }
170→      }
171→
172→      // Remove them
173→      foreach(var key in keysToRemove)
174→      {
175→        _storage.Remove(key);
176→      }
177→    }
178→    finally
179→    {
180→      _lock.Release();
181→    }
182→  }
