184→  public async Task<IReadOnlyList<ChunkInfo>> GetChunkInfo(StorageKey keyPrefix)
185→  {
186→    ThrowIfDisposed();
187→
188→    await _lock.WaitAsync();
189→    try
190→    {
191→      var results = new List<ChunkInfo>();
192→
193→      foreach(var kvp in _storage)
194→      {
195→        var components = kvp.Key.Split('/');
196→        var storageKey = new StorageKey(components);
197→
198→        if(storageKey.StartsWith(keyPrefix))
199→        {
200→          results.Add(new ChunkInfo(storageKey, kvp.Value.Length));
201→        }
202→      }
203→
204→      return results;
205→    }
206→    finally
207→    {
208→      _lock.Release();
209→    }
210→  }
