212→  /// <summary>
213→  /// Clears all data from storage.
214→  /// </summary>
215→  /// <remarks>
216→  /// This method is useful for testing scenarios where you need to reset storage state.
217→  /// </remarks>
218→  public async Task Clear()
219→  {
220→    ThrowIfDisposed();
221→
222→    await _lock.WaitAsync();
223→    try
224→    {
225→      _storage.Clear();
226→    }
227→    finally
228→    {
229→      _lock.Release();
230→    }
231→  }
232→
233→  
234→  
235→  void ThrowIfDisposed()
236→  {
237→    if(_isDisposed)
238→      throw new ObjectDisposedException(nameof(InMemoryStorageAdapter));
239→  }
