220→  /// Handles document discovery for unknown documents.
221→  /// </summary>
222→  public async Task OnMessageReceived(IRepoMessage message)
223→  {
224→    ThrowIfDisposed();
225→
226→    if(message is null) return;
227→    if(message.SenderId is null) return; // Must have sender
228→    var documentIdValue = message.DocumentId?.Value;
229→    if(documentIdValue is null) return; // Must have document ID
230→
231→    var documentId = documentIdValue;
232→    var senderId = message.SenderId.Value;
233→
234→    // Check denylist
235→    if(IsInDenylist(documentId)) return;
236→
237→    // Check access policy
238→    if(!await CanAccess(documentId, senderId).ConfigureAwait(false))
239→    {
240→      // Access denied, don't process message
241→      return;
242→    }
243→
244→    DocSynchronizer? docSync;
245→    bool needsBeginSync = false;
246→
247→    await _lock.WaitAsync().ConfigureAwait(false);
248→    try
249→    {
250→      // Get or create doc synchronizer
251→      docSync = GetOrCreateDocSync(documentId);
252→
253→      // If this is a new document we discovered, request it
254→      var doc = _getDocument(documentId);
255→      if(doc is null && !await docSync.HasPeer(senderId).ConfigureAwait(false))
256→      {
257→        // We don't have this document, trigger discovery
258→        _requestDocument(documentId);
259→      }
260→
261→      // Check if peer needs to be tracked
262→      if(!await docSync.HasPeer(senderId).ConfigureAwait(false))
263→      {
264→        needsBeginSync = true;
265→      }
266→    }
267→    finally
268→    {
269→      _lock.Release();
270→    }
271→
272→    // Begin sync outside the lock to prevent deadlocks
273→    if(needsBeginSync)
274→    {
275→      await docSync.BeginSync(senderId).ConfigureAwait(false);
276→    }
277→
278→    // Process message (outside lock to prevent deadlocks)
279→    await docSync.ReceiveMessage(message, senderId).ConfigureAwait(false);
280→  }
