282→  /// <summary>
283→  /// Notifies the synchronizer that a local document change occurred.
284→  /// </summary>
285→  /// <param name="documentId">The document identifier.</param>
286→  public async Task NotifyDocumentChanged(string documentId)
287→  {
288→    ThrowIfDisposed();
289→
290→    DocSynchronizer? docSync;
291→
292→    await _lock.WaitAsync().ConfigureAwait(false);
293→    try
294→    {
295→      if(!_docSynchronizers.TryGetValue(documentId, out docSync))
296→      {
297→        return;
298→      }
299→    }
