using Six.Automerge.Repository;

namespace Six.Automerge.TextEdit;

/// <summary>
/// High-level wrapper around an Automerge text CRDT that provides
/// cached text/formatting state, debounced change application,
/// and events for text and formatting changes.
/// </summary>
[PublicAPI]
public sealed class TextDocument : IDisposable
{
  readonly DocHandle<object> _handle;
  readonly TextDocumentOptions _options;
  readonly AutomergeObjectId _textObjectId;
  readonly SemaphoreSlim _refreshLock = new(1, 1);

  ChangeDebouncer? _debouncer;
  string _cachedText = string.Empty;
  FormattedText _cachedFormattedText = new([]);
  bool _isLocalChange;
  bool _isDisposed;

  public event EventHandler<TextChangedEventArgs>? TextChanged;
  public event EventHandler<FormattedTextChangedEventArgs>? FormattedTextChanged;

  /// <summary>
  /// Gets the current plain text content.
  /// </summary>
  public string Text => Volatile.Read(ref _cachedText);

  /// <summary>
  /// Gets the current formatted text content.
  /// </summary>
  public FormattedText FormattedText => Volatile.Read(ref _cachedFormattedText);

  /// <summary>
  /// Gets the underlying document handle.
  /// </summary>
  public DocHandle<object> Handle => _handle;

  /// <summary>
  /// Gets the document ID.
  /// </summary>
  public string DocumentId => _handle.DocumentId;

  internal TextDocument(DocHandle<object> handle, AutomergeObjectId textObjectId, TextDocumentOptions options)
  {
    ArgumentNullException.ThrowIfNull(handle);
    ArgumentNullException.ThrowIfNull(textObjectId);
    ArgumentNullException.ThrowIfNull(options);

    _handle = handle;
    _textObjectId = textObjectId;
    _options = options;
  }

  /// <summary>
  /// Creates a new document with a text field and returns a wired <see cref="TextDocument"/>.
  /// </summary>
  /// <param name="repo">The repository to create the document in.</param>
  /// <param name="options">Options controlling the text field key, debounce, and sync settings.</param>
  /// <param name="cancellationToken">Cancellation token.</param>
  /// <returns>A fully initialized <see cref="TextDocument"/>.</returns>
  public static async Task<TextDocument> CreateAsync(
    Repository.Repo repo,
    TextDocumentOptions? options = null,
    CancellationToken cancellationToken = default)
  {
    ArgumentNullException.ThrowIfNull(repo);
    options ??= new TextDocumentOptions();

    var handle = await repo.Create<object>().ConfigureAwait(false);

    AutomergeObjectId textObjectId = default!;
    await handle.ChangeAsync(
      doc =>
      {
        textObjectId = doc.PutObject(doc.RootId, options.TextFieldKey, AutomergeContainerType.Text);
      },
      cancellationToken: cancellationToken).ConfigureAwait(false);

    var textDoc = new TextDocument(handle, textObjectId, options);
    await textDoc.InitializeAsync(cancellationToken).ConfigureAwait(false);
    return textDoc;
  }

  /// <summary>
  /// Opens an existing document, waits for it to be ready, and returns a wired <see cref="TextDocument"/>.
  /// Returns null if the document is not found within the timeout period.
  /// </summary>
  /// <param name="repo">The repository containing the document.</param>
  /// <param name="documentId">The ID of the document to open.</param>
  /// <param name="options">Options controlling the text field key, debounce, and sync settings.</param>
  /// <param name="timeout">Timeout for finding the document. Default: 10 seconds.</param>
  /// <param name="cancellationToken">Cancellation token.</param>
  /// <returns>
  /// A fully initialized <see cref="TextDocument"/>, or null if the document was not found.
  /// </returns>
  public static async Task<TextDocument?> OpenAsync(
    Repository.Repo repo,
    string documentId,
    TextDocumentOptions? options = null,
    TimeSpan? timeout = null,
    CancellationToken cancellationToken = default)
  {
    ArgumentNullException.ThrowIfNull(repo);
    ArgumentException.ThrowIfNullOrWhiteSpace(documentId);
    options ??= new TextDocumentOptions();

    var handle = await repo.Find<object>(documentId, timeout).ConfigureAwait(false);
    if(handle is null)
    {
      return null;
    }

    var textObjectId = await handle.ReadAsync(
      doc => doc.GetObject(doc.RootId, options.TextFieldKey),
      cancellationToken).ConfigureAwait(false);

    if(textObjectId is null)
    {
      return null;
    }

    var textDoc = new TextDocument(handle, textObjectId, options);
    await textDoc.InitializeAsync(cancellationToken).ConfigureAwait(false);
    return textDoc;
  }

  /// <summary>
  /// Initializes the document by reading the current text and spans
  /// from the DocHandle and subscribing to change events.
  /// </summary>
  internal async Task InitializeAsync(CancellationToken cancellationToken = default)
  {
    await RefreshFromDocumentAsync(cancellationToken).ConfigureAwait(false);
    _handle.Changed += OnDocHandleChanged;
  }

  /// <summary>
  /// Applies a text change by diffing the new text against the cached text,
  /// computing a splice, and applying it to the document through the debouncer.
  /// </summary>
  public async Task ApplyTextChangeAsync(string newText, CancellationToken cancellationToken = default)
  {
    EnsureNotDisposed();

    _debouncer ??= new ChangeDebouncer(
      TimeSpan.FromMilliseconds(_options.ChangeDebounceMs),
      FlushTextChangeAsync);

    _debouncer.Schedule(newText);
  }

  /// <summary>
  /// Applies a mark to a range of text.
  /// </summary>
  public async Task ApplyMarkAsync(
    ulong start,
    ulong end,
    string markName,
    string markValue,
    ExpandMode expand = ExpandMode.After,
    CancellationToken cancellationToken = default)
  {
    EnsureNotDisposed();

    // Flush any pending text changes first
    if(_debouncer is not null)
    {
      await _debouncer.FlushAsync().ConfigureAwait(false);
    }

    _isLocalChange = true;
    try
    {
      await _handle.ChangeAsync(
        doc => doc.Mark(_textObjectId, start, end, markName, markValue, expand),
        cancellationToken: cancellationToken).ConfigureAwait(false);
    }
    finally
    {
      _isLocalChange = false;
    }

    await RefreshFromDocumentAsync(cancellationToken).ConfigureAwait(false);
    FormattedTextChanged?.Invoke(this, new FormattedTextChangedEventArgs(_cachedFormattedText, true));
  }

  /// <summary>
  /// Applies a boolean mark to a range of text.
  /// </summary>
  public async Task ApplyMarkAsync(
    ulong start,
    ulong end,
    string markName,
    bool markValue,
    ExpandMode expand = ExpandMode.After,
    CancellationToken cancellationToken = default)
  {
    EnsureNotDisposed();

    if(_debouncer is not null)
    {
      await _debouncer.FlushAsync().ConfigureAwait(false);
    }

    _isLocalChange = true;
    try
    {
      await _handle.ChangeAsync(
        doc => doc.Mark(_textObjectId, start, end, markName, markValue, expand),
        cancellationToken: cancellationToken).ConfigureAwait(false);
    }
    finally
    {
      _isLocalChange = false;
    }

    await RefreshFromDocumentAsync(cancellationToken).ConfigureAwait(false);
    FormattedTextChanged?.Invoke(this, new FormattedTextChangedEventArgs(_cachedFormattedText, true));
  }

  /// <summary>
  /// Removes a mark from a range of text.
  /// </summary>
  public async Task RemoveMarkAsync(
    string markName,
    ulong start,
    ulong end,
    ExpandMode expand = ExpandMode.After,
    CancellationToken cancellationToken = default)
  {
    EnsureNotDisposed();

    if(_debouncer is not null)
    {
      await _debouncer.FlushAsync().ConfigureAwait(false);
    }

    _isLocalChange = true;
    try
    {
      await _handle.ChangeAsync(
        doc => doc.Unmark(_textObjectId, markName, start, end, expand),
        cancellationToken: cancellationToken).ConfigureAwait(false);
    }
    finally
    {
      _isLocalChange = false;
    }

    await RefreshFromDocumentAsync(cancellationToken).ConfigureAwait(false);
    FormattedTextChanged?.Invoke(this, new FormattedTextChangedEventArgs(_cachedFormattedText, true));
  }

  public void Dispose()
  {
    if(_isDisposed)
    {
      return;
    }

    _isDisposed = true;

    if(_options.AutoFlushOnDispose && _debouncer is not null)
    {
      // Best-effort flush — fire and forget since Dispose is synchronous
      try
      {
        _debouncer.FlushAsync().GetAwaiter().GetResult();
      }
      catch(ObjectDisposedException)
      {
        // Handle already disposed
      }
    }

    _handle.Changed -= OnDocHandleChanged;
    _debouncer?.Dispose();
    _refreshLock.Dispose();
  }

  async Task FlushTextChangeAsync(string newText)
  {
    string currentText = _cachedText;
    var splice = TextDiff.ComputeSplice(currentText, newText);

    if(!splice.HasChanges)
    {
      return;
    }

    _isLocalChange = true;
    try
    {
      await _handle.ChangeAsync(
        doc => doc.SpliceText(
          _textObjectId,
          (ulong)splice.Offset,
          splice.DeleteCount,
          splice.InsertText)).ConfigureAwait(false);
    }
    finally
    {
      _isLocalChange = false;
    }

    await RefreshFromDocumentAsync(CancellationToken.None).ConfigureAwait(false);
    TextChanged?.Invoke(this, new TextChangedEventArgs(_cachedText, true));
  }

  void OnDocHandleChanged(object? sender, DocHandleChangeEventArgs<object> e)
  {
    if(_isDisposed || _isLocalChange)
    {
      return;
    }

    _ = HandleRemoteChangeAsync();
  }

  async Task HandleRemoteChangeAsync()
  {
    try
    {
      await RefreshFromDocumentAsync(CancellationToken.None).ConfigureAwait(false);
      TextChanged?.Invoke(this, new TextChangedEventArgs(_cachedText, false));
      FormattedTextChanged?.Invoke(this, new FormattedTextChangedEventArgs(_cachedFormattedText, false));
    }
    catch(ObjectDisposedException)
    {
      // Handle was disposed during async operation
    }
  }

  async Task RefreshFromDocumentAsync(CancellationToken cancellationToken)
  {
    await _refreshLock.WaitAsync(cancellationToken).ConfigureAwait(false);
    try
    {
      var textId = _textObjectId;

      var (text, spans) = await _handle.ReadAsync(
        doc =>
        {
          string t = doc.GetText(textId);
          var s = doc.GetSpans(textId);
          return (t, s);
        },
        cancellationToken).ConfigureAwait(false);

      Volatile.Write(ref _cachedText, text);
      Volatile.Write(ref _cachedFormattedText, FormattedText.FromSpans(spans));
    }
    finally
    {
      _refreshLock.Release();
    }
  }

  void EnsureNotDisposed()
  {
    ObjectDisposedException.ThrowIf(_isDisposed, this);
  }
}

