282→  /// <summary>
283→  /// Gets metadata about all chunks matching a key prefix without loading the full data.
284→  /// This is more efficient than the base implementation as it only reads file metadata.
285→  /// </summary>
286→  public override async Task<IReadOnlyList<ChunkInfo>> GetChunkInfo(StorageKey keyPrefix)
287→  {
288→    ThrowIfDisposed();
289→
290→    var dirPath = GetFilePath(keyPrefix);
291→    var results = new List<ChunkInfo>();
292→
293→    await _lock.WaitAsync();
294→    try
295→    {
296→      // Walk directory tree to find all files
297→      var diskFiles = await WalkDirectory(dirPath);
298→
299→      // Get metadata for each file
300→      foreach(var filePath in diskFiles)
301→      {
302→        // Convert file path back to StorageKey
303→        var relativePath = Path.GetRelativePath(_baseDirectory, filePath);
304→        var components = ParseFilePathToKey(relativePath);
305→        var storageKey = new StorageKey(components);
306→
307→        // Check if key matches prefix
308→        if(storageKey.StartsWith(keyPrefix))
309→        {
310→          // Get file size without loading data
311→          var fileInfo = new FileInfo(filePath);
312→          if(fileInfo.Exists)
313→          {
314→            results.Add(new ChunkInfo(storageKey, (int)fileInfo.Length));
315→          }
316→        }
317→      }
318→
319→      return results;
320→    }
321→    finally
322→    {
323→      _lock.Release();
324→    }
325→  }
326→
327→
328→  /// <summary>
329→  /// Converts a storage key to a file system path using directory sharding.
330→  /// </summary>
331→  /// <remarks>
332→  /// The first key component is split into two parts for sharding:
333→  /// - First 2 characters become a directory (prevents too many files in one dir)
334→  /// - Remaining characters become a subdirectory
335→  /// - Other components are appended as subdirectories
336→  ///
337→  /// Example: ["abc123def", "snapshot", "hash456"]
338→  /// → baseDir/ab/c123def/snapshot/hash456
339→  /// </remarks>
340→  string GetFilePath(StorageKey key)
341→  {
342→    if(key.Components.Count == 0)
343→      throw new ArgumentException("StorageKey must have at least one component");
344→
345→    var firstKey = key.Components[0];
346→    if(firstKey.Length < 2)
347→      throw new ArgumentException($"First key component must be at least 2 chars: {firstKey}");
348→
349→    // Shard: first 2 chars / remaining chars / other components
350→    var shardDir = firstKey[..2];         // First 2 chars
351→    var remaining = firstKey[2..];         // Rest of first key
352→
353→    var pathComponents = new List<string> { _baseDirectory, shardDir, remaining };
354→    pathComponents.AddRange(key.Components.Skip(1));
355→
356→    return Path.Combine(pathComponents.ToArray());
357→  }
358→
359→
360→  /// <summary>
361→  /// Gets the cache key for a storage key (uses ToDebugString for consistency).
362→  /// </summary>
363→  string GetCacheKey(StorageKey key) => key.ToDebugString();
364→
365→
366→  /// <summary>
367→  /// Converts a relative file path back to storage key components.
368→  /// Reverses the sharding: ab/c123/snapshot/hash → ["abc123", "snapshot", "hash"]
369→  /// </summary>

