485→  IRepoMessage? DeserializeMessage(MessageDto messageDto)
486→  {
487→    var senderId = new PeerId(messageDto.SenderId);
488→
489→    DocumentId RequireDocumentId(string? value)
490→    {
491→      if(string.IsNullOrWhiteSpace(value))
492→      {
