494→        throw new InvalidOperationException($"Message type {messageDto.MessageType} missing document ID");
495→      }
496→
497→      return DocumentId.Parse(value);
498→    }
499→
500→    return messageDto.MessageType switch
501→    {
502→      "sync" => new SyncMessage
503→      {
504→        DocumentId = RequireDocumentId(messageDto.DocumentId),
505→        Data = messageDto.Data,
506→        SenderId = senderId
507→      },
508→      "request" => new RequestMessage
509→      {
510→        DocumentId = RequireDocumentId(messageDto.DocumentId),
511→        Data = messageDto.Data,
512→        SenderId = senderId
513→      },
514→      // Note: Ephemeral messages require additional fields (Count, SessionId) that aren't in MessageDto
515→      // These would need to be encoded in the Data field and deserialized here
516→      // For now, we log a warning and skip these messages
517→      "ephemeral" => LogUnsupportedMessage("ephemeral"),
518→      "doc-unavailable" => new DocumentUnavailableMessage
519→      {
520→        DocumentId = RequireDocumentId(messageDto.DocumentId),
521→        SenderId = senderId
522→      },
523→      "doc-snapshot" => new DocumentSnapshotMessage
524→      {
525→        DocumentId = RequireDocumentId(messageDto.DocumentId),
526→        Data = messageDto.Data ?? Array.Empty<byte>(),
527→        SenderId = senderId
528→      },
529→      // Note: RemoteHeadsChangedMessage requires NewHeads which isn't in MessageDto
530→      "remote-heads-changed" => LogUnsupportedMessage("remote-heads-changed"),
531→      // Note: RemoteSubscriptionChangeMessage has readonly DocumentId
532→      "remote-subscription-change" => LogUnsupportedMessage("remote-subscription-change"),
