namespace Six.Automerge.TextEdit;

/// <summary>
/// Queues text changes and flushes them after a configurable silence period.
/// Uses the CancellationTokenSource timer-reset pattern: each new change
/// cancels the previous timer and starts a fresh one, so only the final
/// value in a burst is flushed.
/// </summary>
[PublicAPI]
public sealed class ChangeDebouncer : IDisposable
{
  readonly TimeSpan _silencePeriod;
  readonly Func<string, Task> _flushCallback;
  readonly object _gate = new();

  CancellationTokenSource? _timerCts;
  string? _pendingValue;
  bool _isDisposed;

  public ChangeDebouncer(TimeSpan silencePeriod, Func<string, Task> flushCallback)
  {
    ArgumentNullException.ThrowIfNull(flushCallback);
    _silencePeriod = silencePeriod;
    _flushCallback = flushCallback;
  }

  /// <summary>
  /// Schedules a text change for debounced flushing.
  /// If a previous change is pending, it is replaced by this one
  /// and the timer is reset.
  /// </summary>
  public void Schedule(string newText)
  {
    ObjectDisposedException.ThrowIf(_isDisposed, this);

    lock(_gate)
    {
      _pendingValue = newText;

      // Cancel any existing timer and start a new one
      _timerCts?.Cancel();
      _timerCts?.Dispose();
      _timerCts = new CancellationTokenSource();
      var token = _timerCts.Token;

      _ = DelayThenFlushAsync(token);
    }
  }

  /// <summary>
  /// Immediately flushes any pending change, cancelling the debounce timer.
  /// </summary>
  public async Task FlushAsync()
  {
    string? valueToFlush;

    lock(_gate)
    {
      _timerCts?.Cancel();
      _timerCts?.Dispose();
      _timerCts = null;

      valueToFlush = _pendingValue;
      _pendingValue = null;
    }

    if(valueToFlush is not null)
    {
      await _flushCallback(valueToFlush).ConfigureAwait(false);
    }
  }

  public void Dispose()
  {
    if(_isDisposed)
    {
      return;
    }

    _isDisposed = true;

    lock(_gate)
    {
      _timerCts?.Cancel();
      _timerCts?.Dispose();
      _timerCts = null;
      _pendingValue = null;
    }
  }

  async Task DelayThenFlushAsync(CancellationToken token)
  {
    try
    {
      await Task.Delay(_silencePeriod, token).ConfigureAwait(false);
    }
    catch(TaskCanceledException)
    {
      return;
    }

    string? valueToFlush;
    lock(_gate)
    {
      if(token.IsCancellationRequested)
      {
        return;
      }

      valueToFlush = _pendingValue;
      _pendingValue = null;
    }

    if(valueToFlush is not null)
    {
      await _flushCallback(valueToFlush).ConfigureAwait(false);
    }
  }
}

